"""IMPLEMENT: the plan becomes Luau that runs.

Nine producer stages succeed and `src/` is four empty directories. Everything up
to here plans; nothing writes a game. This is the bottleneck, and closing it is
what turns a verified package into something Rojo can build and Studio can open.

The shape of what it emits matters more than the fact that it emits.

**The game is thin.** Every module here requires WorldKit or GameKit and
configures it from data the layers already decided. A generator that emitted its
own economy would be a second implementation of the thing the SDK ships, drifting
from the one that was verified against `Progression` twenty minutes earlier, and
the game would be running code nothing tested.

**Data is data, not code.** The tier costs, the catalogue and the world spec are
emitted as plain Luau tables in `ReplicatedStorage`, because a number baked into
a function cannot be read back by a validator, compared against the plan, or
changed without touching logic.

**Nothing invents a value.** Every constant traces to a layer: the costs to the
economy designer that verified them, the regions to the world grammar that
validated them, the items to the catalogue that balanced them. Anything the
layers did not decide is absent rather than guessed -- a missing system emits a
stub that *fails loudly on first use*, because a game that quietly does nothing
where a shop should be is worse than one that says the shop was never built.
"""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Sequence


class ImplementError(RuntimeError):
    """The game could not be written, and the message says what was missing."""


def _lua_value(value: Any, indent: int = 0) -> str:
    """A JSON-shaped value as a Lua literal.

    Deliberately not a serialiser with options. One representation, so what a
    validator reads back is what the emitter wrote.
    """

    pad = "\t" * indent
    inner = "\t" * (indent + 1)

    if isinstance(value, bool):
        return "true" if value else "false"
    if value is None:
        return "nil"
    if isinstance(value, (int, float)):
        return repr(round(value, 6) if isinstance(value, float) else value)
    if isinstance(value, str):
        return '"' + value.replace("\\", "\\\\").replace('"', '\\"') + '"'
    if isinstance(value, (list, tuple)):
        if not value:
            return "{}"
        items = ",\n".join(inner + _lua_value(item, indent + 1) for item in value)
        return "{\n" + items + ",\n" + pad + "}"
    if isinstance(value, dict):
        if not value:
            return "{}"
        lines = []
        for key, item in value.items():
            name = str(key)
            label = name if name.isidentifier() else f"[{_lua_value(name)}]"
            lines.append(f"{inner}{label} = {_lua_value(item, indent + 1)}")
        return "{\n" + ",\n".join(lines) + ",\n" + pad + "}"
    raise ImplementError(f"cannot express {type(value).__name__} as a Lua literal")


def _module(name: str, why: str, value: Any) -> str:
    return f"""--!strict
-- {name}
--
-- {why}
--
-- Generated by the RQE implementer from a verified production package. Edit the
-- game model and re-implement; editing this file creates a second description
-- that can disagree with the first.

return {_lua_value(value)}
"""


_FEEDBACK_EVENT_ORDER = (
    "success", "error", "purchase", "reward", "build", "upgrade",
    "unlock", "damage", "wave", "victory", "defeat",
)


def _feedback_events(implemented: set[str], *, has_content: bool) -> list[str]:
    """Presentation events implied by capabilities, never by a genre name."""

    enabled = {"success", "error", "victory", "defeat"}
    if "economy" in implemented:
        enabled.add("reward")
    if "shop" in implemented or ("economy" in implemented and has_content):
        enabled.add("purchase")
    if "progression" in implemented:
        enabled.update(("upgrade", "unlock"))
    if "tower" in implemented:
        enabled.update(("build", "damage", "wave"))
    return [name for name in _FEEDBACK_EVENT_ORDER if name in enabled]


def _feedback_config(
    root: Path,
    game_id: str,
    events: Sequence[str],
) -> dict[str, Any]:
    """Load optional trusted audio overrides, retaining built-ins otherwise.

    `feedback.json` is configuration, not publication evidence. It may select a
    numeric Roblox asset id, but the emitted receipt continues to call that a
    configured id until the asset pipeline proves availability/moderation.
    """

    path = Path(root) / "games" / game_id / "feedback.json"
    document: dict[str, Any] = {}
    if path.is_file():
        try:
            loaded = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            raise ImplementError(f"{path} is not valid feedback configuration: {exc}") from exc
        if not isinstance(loaded, dict):
            raise ImplementError(f"{path} must contain an object")
        unknown = sorted(set(loaded) - {"schemaVersion", "audio"})
        if unknown:
            raise ImplementError(f"{path} has unknown fields: {', '.join(unknown)}")
        document = loaded

    raw_audio = document.get("audio") or {}
    if not isinstance(raw_audio, dict):
        raise ImplementError(f"{path} audio must be an object keyed by semantic event")
    audio: dict[str, Any] = {}
    allowed = set(events)
    for event, value in raw_audio.items():
        if event not in allowed:
            raise ImplementError(
                f"{path} configures audio for {event!r}, but that event is not "
                f"implied by this game's systems ({', '.join(events)})"
            )
        if isinstance(value, (str, int)):
            value = {"assetId": value}
        if not isinstance(value, dict) or set(value) - {
            "assetId", "id", "volume", "pitch", "playbackSpeed"
        }:
            raise ImplementError(
                f"{path} audio.{event} must contain only assetId, volume and pitch"
            )
        asset_id = value.get("assetId", value.get("id"))
        valid_id = (
            isinstance(asset_id, int) and asset_id > 0
            or isinstance(asset_id, str) and (
                asset_id.isdigit()
                or asset_id.startswith("rbxassetid://") and asset_id[13:].isdigit()
                or asset_id.startswith("rbxasset://sounds/")
            )
        )
        if not valid_id:
            raise ImplementError(
                f"{path} audio.{event} needs a positive Roblox asset id or built-in sound path"
            )
        audio[event] = value

    return {
        "schemaVersion": 1,
        "events": list(events),
        "audio": audio,
        "audioFallback": {
            "source": "roblox-builtin",
            "uploadRequired": False,
            "configuredAssetIdsProveModeration": False,
        },
    }


@dataclass
class Implementation:
    """Everything written, and what each file is."""

    game_id: str
    root: Path
    files: dict[str, str] = field(default_factory=dict)
    #: Files removed because this run no longer emits them.
    pruned: list[str] = field(default_factory=list)

    def write(self) -> list[str]:
        written: list[str] = []
        for relative, source in sorted(self.files.items()):
            path = self.root / relative
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(source, encoding="utf-8")
            written.append(relative)
        self.pruned = self._prune(written)
        return written

    def _prune(self, written: list[str]) -> list[str]:
        """Delete Luau under `src/` that this run no longer emits.

        Writing without pruning leaves the previous run's files in place, and
        Rojo packages what is on disk rather than what was emitted. The first
        time it mattered: a game whose missing system had since been authored
        kept its `Missing.lua`, the stub shipped into the built place, and the
        only symptom was six occurrences of a word in a 280 KB XML file.

        Scoped to `src/` and to `.lua`, because everything else in a game
        directory -- the definition, the token set, the built place -- is either
        authored elsewhere or an output.
        """

        source_root = (self.root / "games" / self.game_id / "src").resolve()
        if not source_root.is_dir():
            return []

        keep = {(self.root / name).resolve() for name in written}
        removed: list[str] = []
        for path in sorted(source_root.rglob("*.lua")):
            if path.resolve() not in keep:
                path.unlink()
                removed.append(str(path.relative_to(self.root.resolve())))

        # Directories too, deepest first. Rojo maps a directory to a Folder
        # whether or not anything is in it, so an emptied one becomes an
        # instance with the same name as the module that replaced it -- and
        # `require` resolves to the Folder and fails with "invalid argument",
        # which names neither the file nor the reason.
        for directory in sorted(source_root.rglob("*"), key=lambda p: -len(p.parts)):
            if directory.is_dir() and not any(directory.iterdir()):
                directory.rmdir()
                removed.append(str(directory.relative_to(self.root.resolve())) + "/")
        return removed

    def to_dict(self) -> dict[str, Any]:
        return {
            "schemaVersion": 1,
            "gameId": self.game_id,
            "files": sorted(self.files),
            "pruned": list(self.pruned),
            "lines": sum(source.count("\n") for source in self.files.values()),
            "note": (
                "the game is thin: every module requires the SDK and configures it "
                "from what the layers decided. A generator emitting its own economy "
                "would be a second implementation of the verified one"
            ),
        }


def _ambiguous_statements(files: dict[str, str]) -> list[str]:
    """Lines that start with `(` directly after an expression.

    Luau parses

        local side = f(x)
        (y).Size = 1

    as `f(x)(y).Size = 1`. It compiles -- `luau_check` reports nothing -- and
    then raises "Ambiguous syntax" at runtime, killing every statement after it
    in the same script. Measured cost the one time it shipped: the HUD's whole
    screens section, its menu and both capture bindables disappeared from a
    build that reported OK, and the only symptom was a missing screenshot.

    Checked here rather than left to the compiler because the compiler's own
    verdict is the reason it got through.
    """

    problems: list[str] = []
    for name, source in sorted(files.items()):
        previous = ""
        for number, line in enumerate(source.splitlines(), start=1):
            stripped = line.strip()
            if stripped.startswith("(") and previous and not previous.endswith((
                ";", "then", "do", "else", "{", ",", "(", "or", "and", "=",
            )) and not previous.startswith(("--", "]]")):
                problems.append(
                    f"{name}:{number} starts a statement with '(' after "
                    f"{previous[:48]!r}; Luau reads that as a call on the line "
                    "above and raises Ambiguous syntax at runtime"
                )
            if stripped and not stripped.startswith("--"):
                previous = stripped
    return problems


def _planned_geometry_ids(assets: Any) -> set[str] | None:
    """The mesh ids the geometry stage was asked to build.

    Geometry workspaces survive a run so Blender can reuse its expensive output.
    That also means an old package may remain after the asset plan changes.  The
    plan is the authority for which of those packages belongs to this build; an
    unplanned mesh must not hitch a ride merely because it is still on disk.

    ``None`` means there was no asset plan to constrain discovery.  An empty set
    means there *was* a plan and it requested no Blender-created geometry.
    """

    if assets is None:
        return None
    entries = getattr(assets, "entries", None)
    if entries is None and isinstance(assets, dict):
        entries = assets.get("entries")
    entries = entries or ()

    wanted: set[str] = set()
    for entry in entries:
        if isinstance(entry, dict):
            asset_id = entry.get("id")
            backend = entry.get("backend")
            strategy = entry.get("strategy")
        else:
            asset_id = getattr(entry, "id", None)
            backend = getattr(entry, "backend", None)
            strategy = getattr(entry, "strategy", None)
        # This is the exact selection made by producer.geometry_stage.  Keep the
        # id transformation in lock-step with the AssetBrief it creates.
        if asset_id and backend == "blender" and strategy == "CREATE":
            wanted.add(str(asset_id).replace("-", "_"))
    return wanted


_AUTO_GEOMETRY_PACKAGES = object()


def _geometry_package_roots(
    root: Path,
    game_id: str,
    geometry_packages: Any,
) -> list[Path]:
    """Resolve explicit packages, or derive this game's package directory.

    The producer writes ``.tmp/geometry/<game_id>/asset-*/``.  The old emitter
    read ``.tmp/geometry/kit/`` instead, so Blender could finish successfully
    while none of its modules reached the place.  Explicit packages are also
    accepted so callers that already hold the geometry-stage result do not have
    to rediscover it through the filesystem.
    """

    if geometry_packages is _AUTO_GEOMETRY_PACKAGES:
        workspace = Path(root) / ".tmp" / "geometry" / game_id
        if not workspace.is_dir():
            return []
        return sorted(
            path for path in workspace.glob("asset-*") if path.is_dir()
        )

    # ``None`` and an empty mapping are explicit declarations that this run
    # produced no geometry.  They must not fall back to the persistent .tmp
    # cache: doing so can silently embed a previous run's mesh in a degraded
    # or failed current run.
    if geometry_packages is None:
        return []

    values = (
        geometry_packages.values()
        if isinstance(geometry_packages, dict)
        else geometry_packages
    )
    if isinstance(values, (str, Path)) or not hasattr(values, "__iter__"):
        values = (values,)

    resolved: list[Path] = []
    for package in values:
        expected_brief_sha256 = None
        expected_content_hash = None
        # pathlib.Path itself has a ``root`` property (``\`` on Windows), so
        # recognise path values before the AssetPackage-shaped protocol.
        if isinstance(package, (str, Path)):
            candidate = Path(package)
        elif isinstance(package, dict) and package.get("root"):
            candidate = Path(package["root"])
            expected_brief_sha256 = package.get("expectedBriefSha256")
            expected_content_hash = package.get("expectedContentHash")
        elif hasattr(package, "root"):
            candidate = Path(package.root)
        else:
            raise ImplementError(
                "geometry_packages entries must be AssetPackage objects, paths, "
                "or dictionaries containing 'root'"
            )
        if not candidate.is_absolute():
            # An AssetPackage created from a relative repository root already
            # carries that root in its path (``repo/.tmp/...``).  Prefer the
            # path as supplied when it resolves from the current process;
            # otherwise treat it as relative to the implementation root.
            candidate = candidate if candidate.is_dir() else Path(root) / candidate
        if not candidate.is_dir():
            raise ImplementError(f"geometry package does not exist: {candidate}")
        if expected_brief_sha256 is not None or expected_content_hash is not None:
            from ..geometry import AssetPackage, PackageError

            try:
                opened = AssetPackage.open(candidate)
                manifest = opened.manifest()
            except (PackageError, OSError, json.JSONDecodeError) as exc:
                raise ImplementError(
                    f"geometry package cannot prove its current-run identity: {candidate}: {exc}"
                ) from exc
            if manifest.get("briefSha256") != expected_brief_sha256:
                raise ImplementError(
                    f"geometry package brief hash mismatch for {candidate}: expected "
                    f"{expected_brief_sha256}, observed {manifest.get('briefSha256')}"
                )
            if manifest.get("contentHash") != expected_content_hash:
                raise ImplementError(
                    f"geometry package content hash mismatch for {candidate}: expected "
                    f"{expected_content_hash}, observed {manifest.get('contentHash')}"
                )
            integrity = opened.verify()
            if integrity:
                raise ImplementError(
                    f"geometry package failed its hash-bound inventory: {candidate}: "
                    + "; ".join(integrity)
                )
        resolved.append(candidate)
    return sorted(set(resolved), key=lambda path: path.as_posix())


def _audio_bank(game_root: Path, root: Path, game_id: str) -> dict[str, str]:
    """The sourced audio cues as an emitted module, if any were published.

    Read from the game's own provenance record rather than a global catalogue:
    an asset id belongs to the game it was published for, and a bank shared
    across games is a bank that outlives the licence check that approved it.
    """

    record = root / "games" / game_id / "audio-provenance.json"
    if not record.is_file():
        return {}
    data = json.loads(record.read_text(encoding="utf-8"))
    # Only cues the SDK actually knows. `Audio.define` raises on an unknown
    # event and takes the whole world script down with it -- one cue named
    # "denial" instead of "denied" cost a build that reported OK and a place
    # with no world in it.
    from ..assets.audio_authoring import GENERATORS  # noqa: F401  (import guard)

    known = {"build", "click", "confirm", "damage", "defeat", "denied", "error",
             "purchase", "reward", "success", "unlock", "upgrade", "victory",
             "wave"}
    cues = {name: entry for name, entry in (data.get("cues") or {}).items()
            if isinstance(entry, dict) and entry.get("assetId") and name in known}
    unknown = sorted(set(data.get("cues") or {}) - known)
    if unknown:
        raise ImplementError(
            "audio provenance names cues WorldKit.Audio does not know: "
            + ", ".join(unknown)
            + f"; known events are {', '.join(sorted(known))}"
        )
    if not cues:
        return {}

    lines = [
        "--!strict",
        f"-- Sourced audio for {game_id}.",
        "--",
        f"-- {data.get('licence', 'unknown')} from {data.get('source', 'unknown')}"
        f" ({data.get('sourceUrl', '')}), published through Open Cloud and",
        "-- moderated before this file was written. Generated; edit the",
        "-- provenance record instead.",
        "--",
        f"-- Attribution required: {bool(data.get('attributionRequired'))}",
        "",
        "return {",
    ]
    for name in sorted(cues):
        entry = cues[name]
        lines.append(
            f"\t{name} = {{ assetId = {entry['assetId']!r}, "
            f"volume = 0.6 }}, -- {entry.get('file', '')}"
        )
    lines.append("}")
    lines.append("")
    return {str(game_root / "src/shared/AudioBank.lua"): "\n".join(lines)}


def _mesh_kit(
    game_root: Path,
    root: Path,
    *,
    game_id: str,
    assets: Any = None,
    geometry_packages: Any = None,
) -> dict[str, str]:
    """Emit this game's authored mesh packages as Luau modules.

    Read from the geometry stage's output rather than regenerating it: Blender
    takes minutes and its package is already the measured artifact.  If no
    package exists, the world falls back to Part props.  Packages from a
    different game and stale packages outside the current AssetPlan are never
    considered.
    """

    from ..geometry.luau import catalogue_source, module_source

    wanted = _planned_geometry_ids(assets)
    if wanted == set():
        return {}

    mesh_files: list[Path] = []
    for package_root in _geometry_package_roots(root, game_id, geometry_packages):
        export_root = package_root / "export"
        if export_root.is_dir():
            mesh_files.extend(sorted(export_root.glob("*.mesh.json")))

    files: dict[str, str] = {}
    entries: list[dict[str, Any]] = []
    seen: dict[str, Path] = {}
    for mesh_json in sorted(set(mesh_files), key=lambda path: path.as_posix()):
        data = json.loads(mesh_json.read_text(encoding="utf-8"))
        name = str(data.get("id", ""))
        if wanted is not None and name not in wanted:
            continue
        if not name or not name.replace("_", "").isalnum() or name[0].isdigit():
            raise ImplementError(
                f"geometry mesh id {name!r} from {mesh_json} is not a Luau module name"
            )
        if name in seen:
            raise ImplementError(
                f"two geometry packages export mesh id {name!r}: "
                f"{seen[name]} and {mesh_json}"
            )
        seen[name] = mesh_json

        text = module_source(data)
        files[str(game_root / "src/shared/MeshKit" / f"{name}.lua")] = text
        entries.append({
            "id": name,
            "bytes": len(text.encode("utf-8")),
            "triangles": len(data["indices"]) // 3,
        })

    if entries:
        files[str(game_root / "src/shared/MeshKit/init.lua")] = catalogue_source(entries)
    return files


def _unresolved_requires(files: dict[str, str], game_root: Path) -> list[str]:
    """Requires of `Shared.X` with no `X.lua` emitted beside them.

    `luau-compile` parses; it does not resolve requires, so a module that asks
    for something nobody wrote compiles perfectly and fails the first time the
    place runs. That is the most expensive place to find it -- Studio open, a
    person watching -- for a mistake visible here in a dictionary lookup.
    """

    import re

    emitted = {
        Path(name).stem
        for name in files
        if Path(name).parent.name == "shared" and name.endswith(".lua")
    }
    missing: list[str] = []
    for name, source in files.items():
        if not name.endswith(".lua"):
            continue
        for module in re.findall(r"require\(ReplicatedStorage\.Shared\.(\w+)\)", source):
            if module not in emitted:
                missing.append(f"{Path(name).as_posix()} requires Shared.{module}, which is not emitted")
    return sorted(set(missing))


def implement(
    model: Any,
    *,
    root: Path,
    composition: Any = None,
    economy: Any = None,
    content: dict[str, Any] | None = None,
    world: Any = None,
    assets: Any = None,
    geometry_packages: Any = _AUTO_GEOMETRY_PACKAGES,
    screens: Sequence[str] = (),
) -> Implementation:
    """Write the game from what the layers produced."""

    game_root = Path("games") / model.id
    files: dict[str, str] = {}

    # -- data ------------------------------------------------------------
    #
    # In ReplicatedStorage so the client can read prices and names without a
    # round trip, and so a validator can read them back off disk.

    files[str(game_root / "src/shared/GameConfig.lua")] = _module(
        "GameConfig",
        "The game model, as the running game sees it. Derived from game.json.",
        {
            "id": model.id,
            "genre": model.genre,
            "theme": model.theme,
            "coreLoop": list(model.core_loop),
            "topology": model.topology,
            "tokenSet": model.token_set,
            "concurrentPlayers": model.concurrent_players,
            "privateSpace": model.private_space,
        },
    )

    currencies = [
        {
            "id": currency.id,
            "displayName": currency.display_name,
            "integral": True,
            "startingBalance": 0,
        }
        for currency in model.currencies
    ]
    files[str(game_root / "src/shared/CoreLoop.lua")] = _module(
        "CoreLoop",
        "The loop the design compiler settled on. Emitted so the running game can "
        "state what it is, and so a screen can show the player what to do next.",
        list(model.core_loop),
    )

    files[str(game_root / "src/shared/Currencies.lua")] = _module(
        "Currencies",
        "What the game is denominated in. From the game model's economy.",
        currencies,
    )

    if economy is not None:
        tiers = [
            {
                "id": f"t{index + 1}",
                "index": index + 1,
                "displayName": f"Tier {index + 1}",
                "cost": round(cost, 2),
                "currency": model.currencies[0].id if model.currencies else "cash",
                "incomeMultiplier": 1.0,
            }
            for index, cost in enumerate(economy.tier_costs)
        ]
        files[str(game_root / "src/shared/Tiers.lua")] = _module(
            "Tiers",
            "The cost ladder solved by the economy designer and verified against "
            "Progression.pacing -- these exact numbers measured "
            f"{economy.verified.get('totalMinutes', '?')} minutes.",
            tiers,
        )

    if content is not None:
        catalogue = content.get("catalogue", {})
        files[str(game_root / "src/shared/Catalogue.lua")] = _module(
            "Catalogue",
            f"{catalogue.get('count', 0)} entries across {catalogue.get('tiers', 0)} "
            "tiers, checked for consistency and for balance before being written.",
            catalogue.get("entries", []),
        )

    # The token set, as the running game reads it. Emitted rather than loaded
    # from disk at runtime: a place has no filesystem, and a second loader in
    # Luau would be a second set of rules to drift from the validated one.
    token_relative = model.token_set or "tokens/brickfarm.json"
    token_path = Path(root) / token_relative
    if not token_path.is_file():
        raise ImplementError(
            f"the model names token set {token_relative}, which does not exist. "
            "The game reads its colours, spacing and grammar from it, so emitting "
            "without one would produce a game that cannot start."
        )
    files[str(game_root / "src/shared/TokenData.lua")] = _module(
        "TokenData",
        f"The token set ({token_relative}) as a Lua table, so the place can read "
        "it with no filesystem. Validated against its schema before being written.",
        json.loads(token_path.read_text(encoding="utf-8")),
    )

    # Assets this game has already published, if any. An id here is a mesh
    # Roblox approved; the world builds a MeshPart from it rather than standing
    # in a primitive that looks nothing like what the geometry runtime made.
    published_path = Path(root) / "games" / model.id / "published-assets.json"
    published: list[dict[str, Any]] = []
    if published_path.is_file():
        published = json.loads(published_path.read_text(encoding="utf-8")).get("assets") or []
    files[str(game_root / "src/shared/PublishedAssets.lua")] = _module(
        "PublishedAssets",
        "Meshes this game published and Roblox approved. Empty is honest: it "
        "means nothing has cleared moderation yet, and the world stands in "
        "primitives rather than pretending.",
        published,
    )

    if assets is not None:
        entries = getattr(assets, "entries", None) or (
            assets.get("entries") if isinstance(assets, dict) else []
        )
        files[str(game_root / "src/shared/AssetPlan.lua")] = _module(
            "AssetPlan",
            "What the asset director decided to build, reuse or search for, and at "
            "what budget. Emitted so the running game can report which of its "
            "assets are real and which are still placeholders -- a distinction "
            "that is invisible once everything is grey.",
            [
                entry.to_dict() if hasattr(entry, "to_dict") else dict(entry)
                for entry in entries
            ],
        )

    if world is None:
        # Synthesised rather than skipped: a plaza to stand in and a landmark to
        # look at is the least a world can be, and it keeps the single world
        # path honest for genres the grammar does not yet lay out.
        extent = 320.0
        files[str(game_root / "src/shared/WorldSpec.lua")] = _module(
            "WorldSpec",
            "A minimal layout, synthesised because the world grammar produced none "
            "for this genre. Recorded as synthetic so nobody mistakes it for a "
            "planned one.",
            {
                "id": f"{model.id}-synthetic",
                "synthetic": True,
                "regions": [
                    {"id": "commons", "kind": "plaza", "centre": [0, 0, 0],
                     "size": [extent, extent], "spawn": True, "elevation": 0},
                    {"id": "outskirts", "kind": "field", "centre": [0, 0, extent * 0.8],
                     "size": [extent, extent * 0.7], "spawn": False, "elevation": 0},
                ],
                "circulation": [{"from": "commons", "to": "outskirts", "width": 24}],
                "landmarks": [{"id": "beacon", "at": [0, 0, -extent * 0.3],
                               "height": 48, "visibleFrom": ["commons"]}],
                "sightlines": [],
            },
        )

    if world is not None:
        files[str(game_root / "src/shared/WorldSpec.lua")] = _module(
            "WorldSpec",
            "The blockout the world grammar expanded and the planner validated, "
            "including its reachability walk.",
            world.to_dict(),
        )

    # -- server ----------------------------------------------------------

    systems = list(getattr(composition, "order", ())) or list(model.systems)
    implemented = set(getattr(composition, "implemented", systems))
    planned = [name for name in systems if name not in implemented]
    feedback_events = _feedback_events(implemented, has_content=content is not None)
    feedback_config = _feedback_config(root, model.id, feedback_events)
    files[str(game_root / "src/shared/FeedbackConfig.lua")] = _module(
        "FeedbackConfig",
        "Semantic feedback implied by this game's implemented systems. Audio ids "
        "are trusted local configuration; omitted cues use an explicit Roblox "
        "built-in fallback and never claim an upload or moderation verdict.",
        feedback_config,
    )

    # Tuning derived from the ladder the economy designer verified. Choosing
    # these numbers here would run the game at a pace the pacing report never
    # measured, and the report is the only reason to believe the pace is sane.
    tier_costs = list(getattr(economy, "tier_costs", ()) or ())
    rounds_to_win = max(min(len(tier_costs), 12), 5)
    progression = getattr(model, "progression", None)
    session_minutes = float(getattr(progression, "session_minutes", 0) or 0)
    wave_seconds = (
        round(max(session_minutes * 60.0 / rounds_to_win, 15.0), 1)
        if session_minutes > 0 else 20.0
    )
    tuning = {
        "incomePerSecond": float(getattr(economy, "base_income", 0) or 0) or (
            # First tier reachable in about forty seconds. A first purchase a
            # player cannot see coming is a game they leave before it starts.
            round(tier_costs[0] / 40.0, 3) if tier_costs else 1.0
        ),
        # The session length is a design decision already in the GameModel.
        # Twelve 20-second waves made a promised ten-minute vigil end in four.
        "waveSeconds": wave_seconds,
        "roundsToWin": rounds_to_win,
        "pathLength": 120.0,
        # Give the authored onboarding action time to happen before pressure.
        # Reuse the model's first-progression window, with a bounded floor and
        # ceiling so neither a missing nor an idle-oriented value breaks combat.
        "prepareSeconds": round(max(min(float(
            getattr(progression, "first_tier_seconds", 0) or 0
        ), 45.0), 12.0), 1),
    }

    files[str(game_root / "src/gameplay/Gameplay.lua")] = _gameplay_source(
        model, systems=systems, implemented=implemented, has_economy=economy is not None,
        has_content=content is not None, tuning=tuning,
    )

    files[str(game_root / "src/gameplay/Drivers.lua")] = _drivers_source(model, implemented)

    if planned:
        # A stub that fails on first use, never one that silently succeeds. A
        # game that quietly does nothing where a shop should be is worse than
        # one that says the shop was never built.
        files[str(game_root / "src/gameplay/Missing.lua")] = _missing_source(planned)

    # Always. A game with no world stage used to emit no world script at all,
    # and the result was a place containing Terrain and a Camera: the player
    # spawned at the origin with nothing underneath and fell out of the world.
    # Found by playing one. A genre that declares no zones still needs a floor.
    # The mood and camera come from the token set rather than from a default
    # here: `Tokens.mood` refuses an id it does not know, so emitting a guess
    # produces a game that fails on its first line. Chosen deterministically by
    # game id, so re-running the factory does not relight the world.
    token_document = json.loads(token_path.read_text(encoding="utf-8"))
    moods = sorted(token_document.get("moods") or {})
    cameras = sorted(token_document.get("cameras") or {})
    if not moods or not cameras:
        raise ImplementError(
            f"{token_relative} declares no {'moods' if not moods else 'cameras'}; "
            "a world cannot be lit or framed from it"
        )
    digest = int(hashlib.sha256(model.id.encode("utf-8")).hexdigest()[:8], 16)

    # Chosen from the game's own words, not from a hash of its id.
    #
    # The first version hashed, and handed a medieval tower defense a mood called
    # `farm-night`: the lighting worked perfectly and the first frame was a dark
    # blue rectangle. A hash is deterministic, which is not the same as being a
    # decision -- and arbitrary presentation is most of what makes a generated
    # game feel generated.
    #
    # Matched against the theme and genre; when nothing matches, the daylight
    # mood wins, because a game nobody has lit deliberately should be readable
    # rather than atmospheric.
    words = f"{model.theme} {model.genre} {model.pitch}".lower()
    NIGHT = ("night", "noturno", "dark", "horror", "noite")
    GOLDEN = ("sunset", "golden", "dusk", "entardecer", "autumn")
    OVERCAST = ("storm", "rain", "fog", "overcast", "chuva", "tempestade")

    def _pick(fragments: tuple[str, ...]) -> str | None:
        if not any(word in words for word in fragments):
            return None
        return next((mood for mood in moods if any(f in mood for f in fragments)), None)

    mood = _pick(NIGHT) or _pick(GOLDEN) or _pick(OVERCAST)
    if mood is None:
        daylight = [m for m in moods if any(k in m for k in ("noon", "day", "bright", "dia"))]
        mood = daylight[0] if daylight else moods[0]

    camera = cameras[digest % len(cameras)]
    if any(word in words for word in NIGHT):
        # Dark close-quarters games need the player near the threat. A hashed
        # plot-overview profile put this horror game 40+ studs from its own
        # pilgrim; deterministic is not the same thing as appropriate.
        camera = next(
            (profile for profile in cameras
             if "shoulder" in profile and "mobile" not in profile),
            next((profile for profile in cameras if "shoulder" in profile), camera),
        )

    presentation = {
        "mood": mood,
        "camera": camera,
        "seed": digest % 1_000_000,
        "setpiece": "ruined-sanctuary" if any(
            word in words for word in ("horror", "terror", "abbey", "abadia", "ritual")
        ) else "",
    }

    # One world builder, not two.
    #
    # A second template for games without a layout meant two places where a
    # world could be composed and one of them silently rotted -- it was deleted
    # by an edit to the other and nothing noticed until the tests ran. A game
    # with no spec gets a minimal one synthesised here instead, so every world
    # travels the same path and improvements to it reach every game.
    files[str(game_root / "src/world/init.server.lua")] = _world_source(
        model, presentation, assets is not None)

    # The loop, standing in the world. Under gameplay so it loads after the
    # systems it drives -- a prompt that spends from an economy that does not
    # exist yet fails on the first press, which is the one nobody forgets.
    if content is not None:
        files[str(game_root / "src/gameplay/Playable.lua")] = _playable_source(
            model, presentation)

    # A Script cannot be required, so the systems live in a module and this
    # starts them. Emitting the systems as `init.server.lua` made them a Script,
    # and the loop that tried to require it failed with "invalid argument" --
    # an error that names neither the file nor the reason.
    boot = [
        "--!strict",
        "-- Boot: start the systems, then the loop that uses them.",
        "--",
        "-- Thin on purpose. Everything it starts is a module, so each piece can be",
        "-- required by a test or by another system without running this.",
        "",
        "local Gameplay = require(script.Gameplay)",
        "local Drivers = require(script.Drivers)",
    ]
    if content is not None:
        boot += [
            "local Playable = require(script.Playable)",
            "",
            "-- Subscribe presentation before the authoritative clock starts, so",
            "-- the first wave cannot be emitted into an empty listener set.",
            "Playable.build(Gameplay, Drivers)",
        ]
    boot += [
        "",
        "-- The clock. Everything above declares what exists; this is what makes it",
        "-- happen without the player asking, which is the difference between a",
        "-- world with systems in it and a game.",
        "Drivers.start(Gameplay)",
        "",
        "--[[",
        "	The last line, and it says the game is up.",
        "",
        "	Everything that photographs, measures or tests a game has to know when",
        "	it finished starting, and without this each of them guesses. The",
        "	guesses are all versions of watching the screen stop changing, and they",
        "	are all wrong the same way: a HUD builds its labels in the first frame",
        "	and fills them as answers arrive, so a watcher settles while the game",
        "	is still building itself.",
        "",
        "	Not one generated game emitted this, so every game this factory has",
        "	ever produced was invisible to `forge probe` and `forge gametest` --",
        "	the measurement half of the same repository could not read the",
        "	production half's output.",
        "",
        "	Written as a plain StringValue rather than through `Forge.Debug`,",
        "	because a generated game is built on GameKit and does not have Forge.",
        "	The *signal* is what the tooling reads; which library wrote it is not",
        "	something any reader of it cares about.",
        "]]",
        'local ReplicatedStorage = game:GetService("ReplicatedStorage")',
        'local ready = ReplicatedStorage:FindFirstChild("ForgeReady")',
        "if ready == nil then",
        '	local made = Instance.new("StringValue")',
        '	made.Name = "ForgeReady"',
        "	made.Parent = ReplicatedStorage",
        "	ready = made",
        "end",
        "-- Narrowed with `IsA` rather than cast. A cast would start the",
        "-- statement with `(`, which Luau reads as a call on the line above.",
        'if ready ~= nil and ready:IsA("StringValue") then',
        f"	ready.Value = {_lua_value(model.id)}",
        "end",
        "",
        "return nil",
        "",
    ]
    files[str(game_root / "src/gameplay/init.server.lua")] = chr(10).join(boot)

    files[str(game_root / "src/telemetry/init.server.lua")] = _telemetry_source(model)

    # Feedback is a baseline capability, not an optional menu. Even a game with
    # no derived screens needs to tell a player that an action succeeded or was
    # refused, so every emitted place gets the client presenter.
    files[str(game_root / "src/interface/init.client.lua")] = _interface_source(
        model, screens)

    files.update(_audio_bank(game_root, root, model.id))
    files.update(_mesh_kit(
        game_root,
        root,
        game_id=model.id,
        assets=assets,
        geometry_packages=geometry_packages,
    ))

    files[str(game_root / "default.project.json")] = _project_source(model, world is not None)

    # A game nobody can stand in is not a game. Checked here rather than left to
    # a player: the symptom -- falling through the world at spawn -- looks like a
    # physics bug and is actually an empty Workspace.
    # Two ways a game gets somewhere to stand, and both count: the placeholder
    # floor creates a SpawnLocation directly, and a real layout gets one from
    # `Blockout.build`, which places it in the region the spec marks as spawn.
    #
    # The first version of this check looked for the literal string and rejected
    # every game that had an actual world -- a guard that fired on exactly the
    # cases it was meant to bless.
    grounded = any(
        "SpawnLocation" in source or "Blockout.build" in source
        for source in files.values()
    )
    if not grounded:
        raise ImplementError(
            "nothing in this game creates a SpawnLocation, so the player spawns at "
            "the origin and falls out of the world"
        )

    ambiguous = _ambiguous_statements(files)
    dangling = _unresolved_requires(files, game_root)
    if dangling:
        raise ImplementError(
            "the emitted game requires modules it does not write: " + "; ".join(dangling)
        )
    if ambiguous:
        raise ImplementError(
            "the emitted game has statements Luau will refuse at runtime while "
            "compiling clean: " + "; ".join(ambiguous)
        )
    return Implementation(game_id=model.id, root=root, files=files)


def _gameplay_source(model: Any, *, systems: Sequence[str], implemented: set[str],
                     has_economy: bool, has_content: bool,
                     tuning: dict[str, Any]) -> str:
    """Every implemented system constructed, and the core loop as behaviour.

    The version this replaces required the catalogue and never read it,
    constructed three of five systems, and printed the ladder it had been handed.
    Everything the layers decided was present in the project and absent from the
    game -- which is the harder failure to see, because a file count says it
    shipped.

    What "assembled" means here, concretely:

    **Constructed, not listed.** A system in a table is documentation. A system
    passed its catalogue and given somewhere to write is a system.

    **The catalogue feeds the genre's system.** Forty-eight generated entries are
    cards in a collector, towers and enemies in a defense. Emitting them as data
    nothing consumes was the single largest drop.

    **The loop is a loop.** Something to do, something it pays, and something to
    spend it on -- reachable from the world rather than described in a comment.
    """

    currency = model.currencies[0].id if model.currencies else "cash"
    q = chr(34)
    income = round(float(tuning.get("incomePerSecond", 1.0)), 3)
    wave_seconds = round(float(tuning.get("waveSeconds", 20.0)), 1)
    rounds = int(tuning.get("roundsToWin", 8))
    path_length = round(float(tuning.get("pathLength", 120.0)), 1)
    prepare_seconds = round(float(tuning.get("prepareSeconds", 12.0)), 1)

    lines = [
        "--!strict",
        "-- Gameplay: the systems this game runs on, constructed and wired.",
        "--",
        "-- Every system here is GameKit's, configured from what the layers decided.",
        "-- Writing another economy would be a second implementation of the one the",
        "-- pacing was verified against.",
        "",
        'local ReplicatedStorage = game:GetService("ReplicatedStorage")',
        'local Players = game:GetService("Players")',
        "",
        "local GameKit = require(ReplicatedStorage.GameKit)",
        "local Currencies = require(ReplicatedStorage.Shared.Currencies)",
        "local CoreLoop = require(ReplicatedStorage.Shared.CoreLoop)",
        "local FeedbackConfig = require(ReplicatedStorage.Shared.FeedbackConfig)",
    ]
    if has_economy:
        lines.append("local Tiers = require(ReplicatedStorage.Shared.Tiers)")
    if has_content:
        lines.append("local Catalogue = require(ReplicatedStorage.Shared.Catalogue)")
    lines += [
        "", "local Gameplay = {}", "local systems = {}", "",
        "-- Created by the server. It carries facts from authoritative systems to",
        "-- presentation and has no OnServerEvent handler.",
        "systems.feedback = GameKit.Feedback.server(FeedbackConfig)",
        "",
    ]

    if "economy" in implemented and has_content:
        lines += [
            "systems.onboarding = GameKit.Onboarding.define({",
            "\tid = " + q + model.id + ".first-session" + q + ",",
            "\tsteps = {",
            "\t\t{ id = " + q + "earn" + q + ", instruction = " + q + "Collect your first reward" + q + ",",
            "\t\t\tevent = " + q + "reward_collected" + q + ", targetId = " + q + "reward-source" + q + " },",
            "\t\t{ id = " + q + "purchase" + q + ", instruction = " + q + "Use it at the highlighted site" + q + ",",
            "\t\t\tevent = " + q + "purchase_committed" + q + ", targetId = " + q + "first-purchase" + q + " },",
            "\t},",
            "}, GameKit.Onboarding.memoryStore(), function(player: Player, snapshot: { [string]: any })",
            "\t-- The snapshot is authoritative. The HUD presents this attribute; it",
            "\t-- never advances onboarding or claims that an action succeeded.",
            "\tplayer:SetAttribute(" + q + "RQEOnboardingInstruction" + q + ", snapshot.instruction or " + q + q + ")",
            "end)",
            "",
        ]

    if "analytics" in implemented:
        lines += ["systems.analytics = GameKit.Analytics", ""]
    if "economy" in implemented:
        lines += [
            "systems.economy = GameKit.Economy.define(Currencies, GameKit.Economy.memoryStore())",
            "",
        ]
    if "save" in implemented:
        lines += [
            "systems.save = GameKit.Save.store(" + q + model.id + q + ", {",
            "	balance = 0, tier = 1,",
            "})",
            "",
        ]
    if "progression" in implemented and has_economy:
        lines += [
            "systems.progression = GameKit.Progression.define(Tiers)",
            "-- Measured with the same call the economy designer made. A ladder checked",
            "-- only offline is one the shipped game can disagree with.",
            "local pacing = GameKit.Progression.pacing(systems.progression, 1)",
            "",
        ]

    if has_content:
        lines += [
            "-- The generated catalogue, shaped for the systems that consume it. This",
            "-- was the largest single drop: entries emitted and read by nothing.",
            "local items, towers, enemies = {}, {}, {}",
            "for _, entry in ipairs(Catalogue) do",
            "\tlocal stats = entry.stats or {}",
            "\ttable.insert(items, { id = entry.id, displayName = entry.name, stackSize = 20 })",
            "\tif entry.role == " + q + "melee" + q + " or entry.role == " + q + "ranged" + q + " then",
            "\t\ttable.insert(towers, {",
            "\t\t\tid = entry.id, displayName = entry.name,",
            "\t\t\tdamage = math.max(stats.attack or 1, 1),",
            "\t\t\trange = 12 + (stats.speed or 1) * 4,",
            "\t\t\tcost = math.max(math.floor((entry.power or 10) * 5), 1),",
            "\t\t\tcurrency = " + q + currency + q + ",",
            "\t\t})",
            "\telse",
            "\t\ttable.insert(enemies, {",
            "\t\t\tid = entry.id, displayName = entry.name,",
            "\t\t\thealth = math.max((stats.health or 1) * 20, 20),",
            "\t\t\tspeed = math.max(stats.speed or 1, 1) * 3,",
            "\t\t\tbounty = math.max(math.floor(entry.power or 1), 1),",
            "\t\t\tleak = 1,",
            "\t\t})",
            "\tend",
            "end",
            "",
        ]

    if "inventory" in implemented and has_content:
        lines += [
            "systems.inventory = GameKit.Inventory.define(items, GameKit.Inventory.memoryStore(), 24)",
            "",
        ]
    if "shop" in implemented and has_content:
        lines += [
            "-- Offers drawn from the catalogue, so the shop sells this game's content",
            "-- rather than a placeholder list.",
            "local offers = {}",
            "for index, entry in ipairs(Catalogue) do",
            "\tif index > 12 then break end",
            "\ttable.insert(offers, {",
            "\t\tid = entry.id, displayName = entry.name,",
            "\t\tprice = math.max(math.floor((entry.power or 10) * 4), 1),",
            "\t\tcurrency = " + q + currency + q + ", grants = " + q + "item:" + q + " .. entry.id,",
            "\t})",
            "end",
            "systems.shop = GameKit.Shop.define(offers, systems.economy, GameKit.Shop.memoryLedger())",
            "",
        ]
    if "leaderboard" in implemented:
        lines += [
            "systems.leaderboard = GameKit.Leaderboard.define({",
            "\t{ id = " + q + "wealth" + q + ", displayName = " + q + "Richest" + q + " },",
            "}, GameKit.Leaderboard.memoryStore())",
            "",
        ]
    if "tower" in implemented and has_content:
        lines += [
            "-- Waves built from the enemy tiers the content layer produced.",
            "local waves = {}",
            "for index = 1, math.min(#enemies, 8) do",
            "\ttable.insert(waves, {",
            "\t\tindex = index,",
            "\t\tentries = { { enemyId = enemies[index].id, count = 4 + index * 2, interval = 1 } },",
            "\t})",
            "end",
            "if #towers > 0 and #waves > 0 then",
            "\tsystems.tower = GameKit.Tower.define(towers, enemies, waves, GameKit.Tower.memoryStore(), 100)",
            "end",
            "",
        ]

    lines += [
        "-- The loop, as behaviour rather than as a comment.",
        "function Gameplay.reward(player: Player, amount: number, reason: string): number",
    ]
    if "economy" in implemented:
        lines += [
            "\tlocal balance = systems.economy:grant(player, " + q + currency + q + ", amount, reason)",
            "\t-- Published as an attribute so the HUD can read it without a remote.",
            "\t-- The server owns the number; a client keeping its own disagrees with",
            "\t-- the ledger the moment anything is spent, always in its own favour.",
            "\tplayer:SetAttribute(" + q + currency + q + ", balance)",
            "\tif systems.leaderboard ~= nil then",
            "\t\tsystems.leaderboard.submit(player, " + q + "wealth" + q + ", math.floor(balance))",
            "\tend",
            "\tif reason ~= " + q + "production" + q + " then",
            "\t\tsystems.feedback:emit(player, " + q + "reward" + q + ", { amount = amount })",
            "\t\tif systems.onboarding ~= nil then",
            "\t\t\tsystems.onboarding.observe(player, " + q + "reward_collected" + q + ",",
            "\t\t\t\treason .. " + q + ":" + q + " .. tostring(balance), { amount = amount })",
            "\t\tend",
            "\tend",
            "\treturn balance",
        ]
    else:
        lines += ["\terror(" + q + "this game has no economy to reward from" + q + ", 0)"]
    lines += [
        "end",
        "",
        "-- Tuning the drivers read. Derived rather than chosen here: the income",
        "-- comes from the ladder the economy designer verified, so a driver cannot",
        "-- run the game at a pace the pacing report never saw.",
        "Gameplay.incomePerSecond = " + str(income),
        "Gameplay.waveSeconds = " + str(wave_seconds),
        "Gameplay.roundsToWin = " + str(rounds),
        "Gameplay.pathLength = " + str(path_length),
        "Gameplay.prepareSeconds = " + str(prepare_seconds),
        "",
        "function Gameplay.systems(): { [string]: any }",
        "\treturn systems",
        "end",
        "",
        "function Gameplay.loop(): { string }",
        "\treturn CoreLoop",
        "end",
        "",
        "local constructed = 0",
        "for _ in pairs(systems) do constructed += 1 end",
        "print(string.format(" + q + "[" + model.id + "] gameplay: %d systems, %d loop steps" + q + ",",
        "\tconstructed, #CoreLoop))",
        "",
        "return Gameplay",
        "",
    ]
    return chr(10).join(lines)


def _drivers_source(model: Any, implemented: set[str]) -> str:
    """The loop, driven. One driver per system rather than one per genre.

    Systems that exist and nothing that runs them is the state this closes. The
    Tower module was constructed with 24 towers, 24 enemies and 8 waves, and no
    wave ever arrived; the ladder had twelve tiers and nothing ever rose one.
    The only income was a player pressing a prompt.

    What was missing is one thing and it is universal: **a clock**. Every game
    has something that happens without being asked -- production accrues, waves
    arrive, time runs out. Without it there is no pressure, so no decision, so
    no game.

    Driven per system, not per genre, because the systems already differ per
    game: the composer resolves them from the IR. A tower defense gets waves
    because it has `tower`; a simulator gets production because it has `economy`
    and `inventory`. Neither needs code of its own, and a genre nobody has
    thought of yet gets whichever drivers its systems imply.

    A genre-shaped driver would have been the easy version and the wrong one --
    the same mistake as a `Playable` that builds pads for a racing game.
    """

    q = chr(34)
    currency = model.currencies[0].id if model.currencies else "cash"
    lines = [
        "--!strict",
        "-- Drivers: what happens without the player asking.",
        "--",
        "-- One driver per system. The systems differ per game because the composer",
        "-- resolves them from the IR, so this file differs per game without any",
        "-- genre ever being named in it.",
        "",
        'local Players = game:GetService("Players")',
        'local RunService = game:GetService("RunService")',
        "",
        "local Drivers = {}",
        "",
        "--- Session state, which every genre has and no genre owns.",
        "---",
        "--- start -> pressure -> resolution -> reward -> repeat. Win and loss are",
        "--- states of this machine rather than rules of any one game.",
        "local session = {",
        "\tstate = " + q + "PREPARING" + q + ",",
        "\tround = 0,",
        "\telapsed = 0,",
        "\tintegrity = 100,",
        "}",
        "Drivers.session = session",
        "",
        "local listeners: { (string, { [string]: any }) -> () } = {}",
        "",
        "--- Announce a state change once, in one place.",
        "---",
        "--- Every driver reports through here so the HUD, the VFX and the analytics",
        "--- see the same event. Three subsystems each deciding when a wave started",
        "--- is how they disagree about which wave it is.",
        "function Drivers.emit(event: string, detail: { [string]: any }?)",
        "\tlocal payload = detail or {}",
        "\t-- Published as player attributes, which is what the HUD reads. An",
        "\t-- event nothing writes down is an event the interface cannot show,",
        "\t-- and a HUD polling the session would eventually disagree with it",
        "\t-- about which wave it is.",
        "\tfor _, who in ipairs(Players:GetPlayers()) do",
        "\t\twho:SetAttribute(" + q + "sessionState" + q + ", session.state)",
        "\t\twho:SetAttribute(" + q + "wave" + q + ", session.round)",
        "\t\twho:SetAttribute(" + q + "integrity" + q + ", session.integrity)",
        "\tend",
        "\tfor _, listener in ipairs(listeners) do",
        "\t\ttask.spawn(listener, event, payload)",
        "\tend",
        "end",
        "",
        "function Drivers.on(listener: (string, { [string]: any }) -> ())",
        "\ttable.insert(listeners, listener)",
        "end",
        "",
        "function Drivers.start(Gameplay)",
        "\tlocal systems = Gameplay.systems()",
        "",
        "\tlocal function feedback(event: string, detail: { [string]: any }?)",
        "\t\tif event == " + q + "tier" + q + " then",
        "\t\t\tlocal player = detail and detail.player",
        "\t\t\tif player ~= nil then systems.feedback:emit(player, " + q + "upgrade" + q + ",",
        "\t\t\t\t{ itemName = tostring(detail.tier or " + q + "Tier" + q + ") }) end",
        "\t\telseif event == " + q + "wave" + q + " then",
        "\t\t\tsystems.feedback:broadcast(" + q + "wave" + q + ", { round = session.round })",
        "\t\telseif event == " + q + "wave_cleared" + q + " then",
        "\t\t\tsystems.feedback:broadcast(" + q + "reward" + q + ", {})",
        "\t\telseif event == " + q + "leak" + q + " then",
        "\t\t\tsystems.feedback:broadcast(" + q + "damage" + q + ", { amount = 25 })",
        "\t\telseif event == " + q + "victory" + q + " or event == " + q + "defeat" + q + " then",
        "\t\t\tsystems.feedback:broadcast(event, { round = session.round })",
        "\t\tend",
        "\tend",
        "\tDrivers.on(feedback)",
        "",
    ]

    if "economy" in implemented:
        lines += [
            "\t-- Production. The clock that makes every cost reachable, and the reason",
            "\t-- a player has anything to decide between two prompts.",
            "\tlocal accrued = 0",
            "\tRunService.Heartbeat:Connect(function(delta: number)",
            "\t\tif session.state ~= " + q + "ACTIVE" + q + " then",
            "\t\t\treturn",
            "\t\tend",
            "\t\taccrued += delta",
            "\t\tif accrued < 1 then",
            "\t\t\treturn",
            "\t\tend",
            "\t\taccrued -= 1",
            "\t\tfor _, player in ipairs(Players:GetPlayers()) do",
            "\t\t\t-- Scaled by the tier the player has reached, so progression is",
            "\t\t\t-- felt as speed rather than read as a number.",
            "\t\t\tlocal multiplier = 1",
            "\t\t\tif systems.progression ~= nil then",
            "\t\t\t\tlocal tierId = player:GetAttribute(" + q + "tierId" + q + ")",
            "\t\t\t\tmultiplier = systems.progression:multiplierAt(tierId)",
            "\t\t\tend",
            "\t\t\tlocal balance = systems.economy:grant(player, " + q + currency + q + ",",
            "\t\t\t\tGameplay.incomePerSecond * multiplier, " + q + "production" + q + ")",
            "\t\t\tplayer:SetAttribute(" + q + currency + q + ", balance)",
            "\t\tend",
            "\tend)",
            "",
        ]

    if "progression" in implemented:
        lines += [
            "\t-- Advancement. A ladder nothing climbs is a table of numbers; this is",
            "\t-- what turns a balance into a sense of getting somewhere.",
            "\tRunService.Heartbeat:Connect(function()",
            "\t\tif session.state ~= " + q + "ACTIVE" + q + " or systems.economy == nil then",
            "\t\t\treturn",
            "\t\tend",
            "\t\tfor _, player in ipairs(Players:GetPlayers()) do",
            "\t\t\t-- Preserve the tutorial's earned currency until its promised",
            "\t\t\t-- purchase commits. Automatic tier spending used to consume the",
            "\t\t\t-- reward between the reliquary and the highlighted foundation.",
            "\t\t\tif systems.onboarding ~= nil",
            "\t\t\t\tand player:GetAttribute(" + q + "RQEOnboardingComplete" + q + ") ~= true then",
            "\t\t\t\tcontinue",
            "\t\t\tend",
            "\t\t\tlocal current = player:GetAttribute(" + q + "tierId" + q + ")",
            "\t\t\tlocal next = systems.progression:nextAfter(current)",
            "\t\t\tif next ~= nil then",
            "\t\t\t\tplayer:SetAttribute(" + q + "nextCost" + q + ", next.cost)",
            "\t\t\t\tplayer:SetAttribute(" + q + "nextTier" + q + ", next.displayName)",
            "\t\t\t\tlocal balance = systems.economy:balance(player, " + q + currency + q + ")",
            "\t\t\t\tif balance >= next.cost then",
            "\t\t\t\t\tlocal paid = systems.economy:spend(player, " + q + currency + q + ",",
            "\t\t\t\t\t\tnext.cost, " + q + "tier:" + q + " .. next.id)",
            "\t\t\t\t\tif paid then",
            "\t\t\t\t\t\tplayer:SetAttribute(" + q + "tierId" + q + ", next.id)",
            "\t\t\t\t\t\tplayer:SetAttribute(" + q + currency + q + ",",
            "\t\t\t\t\t\t\tsystems.economy:balance(player, " + q + currency + q + "))",
            "\t\t\t\t\t\tDrivers.emit(" + q + "tier" + q + ", { player = player, tier = next.displayName })",
            "\t\t\t\t\tend",
            "\t\t\t\tend",
            "\t\t\tend",
            "\t\tend",
            "\tend)",
            "",
        ]

    if "tower" in implemented:
        lines += [
            "\t-- Pressure. The waves the Tower module already validated, arriving.",
            "\t-- Simulated rather than re-implemented: `Tower.simulate` decides whether",
            "\t-- the defence holds, so the number a player sees is the number the",
            "\t-- balance check used.",
            "\ttask.spawn(function()",
            "\t\twhile true do",
            "\t\t\tif session.state == " + q + "ACTIVE" + q + " then",
            "\t\t\t\tsession.round += 1",
            "\t\t\t\tDrivers.emit(" + q + "wave" + q + ", { round = session.round })",
            "\t\t\t\ttask.wait(Gameplay.waveSeconds)",
            "",
            "\t\t\t\tlocal held = true",
            "\t\t\t\tfor _, player in ipairs(Players:GetPlayers()) do",
            "\t\t\t\t\tlocal report = systems.tower.forecast(player, Gameplay.pathLength)",
            "\t\t\t\t\tlocal wave = report.waves[math.min(session.round, #report.waves)]",
            "\t\t\t\t\tif wave ~= nil and not wave.clearable then",
            "\t\t\t\t\t\theld = false",
            "\t\t\t\t\telseif wave ~= nil and systems.economy ~= nil then",
            "\t\t\t\t\t\tlocal balance = systems.economy:grant(player, " + q + currency + q + ",",
            "\t\t\t\t\t\t\twave.bounty, " + q + "wave" + q + ")",
            "\t\t\t\t\t\tplayer:SetAttribute(" + q + currency + q + ", balance)",
            "\t\t\t\t\tend",
            "\t\t\t\tend",
            "",
            "\t\t\t\tif held then",
            "\t\t\t\t\tDrivers.emit(" + q + "wave_cleared" + q + ", { round = session.round })",
            "\t\t\t\telse",
            "\t\t\t\t\t-- Damage to what the player is defending, which is the only",
            "\t\t\t\t\t-- thing that makes losing possible and therefore winning mean",
            "\t\t\t\t\t-- anything.",
            "\t\t\t\t\tsession.integrity -= 25",
            "\t\t\t\t\tDrivers.emit(" + q + "leak" + q + ", { integrity = session.integrity })",
            "\t\t\t\t\tif session.integrity <= 0 then",
            "\t\t\t\t\t\tsession.state = " + q + "DEFEAT" + q + "",
            "\t\t\t\t\t\tDrivers.emit(" + q + "defeat" + q + ", { round = session.round })",
            "\t\t\t\t\tend",
            "\t\t\t\tend",
            "",
            "\t\t\t\tif session.round >= Gameplay.roundsToWin and session.state == " + q + "ACTIVE" + q + " then",
            "\t\t\t\t\tsession.state = " + q + "VICTORY" + q + "",
            "\t\t\t\t\tDrivers.emit(" + q + "victory" + q + ", { round = session.round })",
            "\t\t\t\tend",
            "\t\t\telse",
            "\t\t\t\ttask.wait(0.5)",
            "\t\t\tend",
            "\t\tend",
            "\tend)",
            "",
        ]

    lines += [
        "\t-- The session opens once somebody is here to play it. Starting on an",
        "\t-- empty server burns rounds nobody sees and greets the first arrival",
        "\t-- mid-defeat.",
        "\tlocal joined: { [number]: boolean } = {}",
        "\tlocal function onPlayer(player: Player)",
        "\t\tif joined[player.UserId] then return end",
        "\t\tjoined[player.UserId] = true",
        "\t\tplayer:SetAttribute(" + q + "tierId" + q + ", nil)",
        "\t\tif systems.onboarding ~= nil then systems.onboarding.start(player) end",
        "\t\tif session.state == " + q + "PREPARING" + q + " then",
        "\t\t\ttask.spawn(function()",
        "\t\t\t\ttask.wait(Gameplay.prepareSeconds)",
        "\t\t\t\tif session.state == " + q + "PREPARING" + q + " then",
        "\t\t\t\t\tsession.state = " + q + "ACTIVE" + q + "",
        "\t\t\t\t\tDrivers.emit(" + q + "session" + q + ", { state = session.state })",
        "\t\t\t\tend",
        "\t\t\tend)",
        "\t\tend",
        "\tend",
        "\tPlayers.PlayerAdded:Connect(onPlayer)",
        "\tfor _, player in ipairs(Players:GetPlayers()) do onPlayer(player) end",
        "",
        "\tRunService.Heartbeat:Connect(function(delta: number)",
        "\t\tif session.state == " + q + "ACTIVE" + q + " then",
        "\t\t\tsession.elapsed += delta",
        "\t\tend",
        "\tend)",
        "",
        "\treturn session",
        "end",
        "",
        "return Drivers",
        "",
    ]
    return chr(10).join(lines)


def _missing_source(planned: Sequence[str]) -> str:
    entries = ",\n".join(
        f'\t{name} = "the {name} system is planned in the SDK and has no module yet; '
        f'this game declared it and nothing implements it"'
        for name in planned
    )
    return f"""--!strict
-- Systems this game asked for that the SDK does not implement yet.
--
-- Each is a function that raises. A stub returning a plausible empty value is
-- how a shop ships with nothing to sell and nobody notices until a player
-- clicks Buy: the game does not crash, it just quietly does nothing where a
-- feature should be. Failing on first use puts the gap where it can be seen.

local reasons = {{
{entries}
}}

local Missing = {{}}

function Missing.require(name: string): never
\tlocal reason = reasons[name]
\terror("[Missing] " .. (reason or ("unknown system " .. name)), 0)
end

function Missing.list(): {{ string }}
\tlocal names = {{}}
\tfor name in pairs(reasons) do
\t\ttable.insert(names, name)
\tend
\ttable.sort(names)
\treturn names
end

return Missing
"""


_SPEC_WORLD_TEMPLATE = '--!strict\n-- World: the validated layout, built and then inhabited.\n--\n-- The blockout was already here and it was all that was here. `Blockout.build`\n-- produces the regions and routes the planner validated -- correct, walkable,\n-- and visually a set of coloured plates. A capture of it scored 22/100 on\n-- environment density, with 90% of the frame one unbroken plane.\n--\n-- What this adds is the difference between a layout and a place, and it is\n-- driven by the region *kind* rather than by the game, so a plaza in a tower\n-- defense and a plaza in a simulator are built the same way and neither is\n-- special-cased:\n--\n--   plaza / spawn     terraced ground, banners, lamps -- somewhere to stand\n--   shop / interior   buildings with doors facing the circulation\n--   landmark          a keep with a beacon, tall enough to read from anywhere\n--   field / plot      planting and rock, kept clear of the routes\n--   corridor / street lamps along it, buildings lining it\n--\n-- Two things are deliberately global rather than per region:\n--\n-- **A perimeter.** The single largest contributor to the flat-plane measurement\n-- is the horizon, and no density inside the play space removes it. Walls with\n-- towers close the world off and give every outward view something to end on.\n--\n-- **Relief.** Ground at one elevation reads as a floor plan in perspective\n-- regardless of what stands on it.\n--\n-- Every proportion comes from the token grammar and every colour from a palette\n-- role, so a change of kit moves the whole world instead of half of it.\n\nlocal ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal Players = game:GetService("Players")\n\nlocal WorldKit = require(ReplicatedStorage.WorldKit)\nlocal WorldSpec = require(ReplicatedStorage.Shared.WorldSpec)\nlocal TokenData = require(ReplicatedStorage.Shared.TokenData)\n{asset_require}\nlocal tokens = WorldKit.Tokens.define(TokenData)\n\n-- Sourced audio, when this game published any.\n--\n-- Five CC0 cues were downloaded, uploaded, moderated and approved, and\n-- the game still played the Roblox built-in button.wav because nothing\n-- called `Audio.define`. The capability, the asset and the call site all\n-- existed; no line connected them.\nlocal audioBank = ReplicatedStorage.Shared:FindFirstChild("AudioBank")\nif audioBank ~= nil then\n\tWorldKit.Audio.define(require(audioBank))\nend\n\n-- The authored kit, when this game has one.\n--\n-- Blender builds the kit, the geometry stage exports it as data modules,\n-- and `WorldKit.Mesh` turns that into real MeshParts at runtime with no\n-- upload and no asset ids. This single line is what puts them in the\n-- world: every scatter loop below already goes through `Props.build`.\n--\n-- Optional on purpose. A game with no kit builds the Part props it always\n-- did, so the geometry stage failing degrades the look instead of the\n-- build.\nlocal meshKit = ReplicatedStorage.Shared:FindFirstChild("MeshKit")\nif meshKit ~= nil then\n\tWorldKit.Props.useKit(require(meshKit))\nend\nlocal MOOD = "{mood}"\nlocal CAMERA_PROFILE = "{camera}"\nlocal SEED = {seed}\n\nlocal random = Random.new(SEED)\n\nlocal STYLE = {{\n\twall = "stonePrimary",\n\ttrim = "stoneSecondary",\n\troof = "structureSecondary",\n\t-- Three roof tones instead of one. A town with a single roof colour\n\t-- reads as one material from above, which is most of why an aerial\n\t-- capture of this map measured three distinct hues in the whole\n\t-- frame. Each building picks from its own seed, so the choice is\n\t-- stable across rebuilds.\n\troofTones = {{ "structureSecondary", "pathPrimary", "woodPrimary" }},\n\taccent = "accentGold",\n}}\n\n-- Light first: three props under default lighting read worse than an empty\n-- scene under a considered sky, and it costs one call.\nlocal applied = WorldKit.Mood.apply(tokens, MOOD)\n\n-- The spec arrives as plain data; Vector types are rebuilt here rather than\n-- serialised, because a stored Vector3 is a table that merely looks like one.\nlocal spec = {{\n\tid = WorldSpec.id,\n\tregions = {{}},\n\tcirculation = WorldSpec.circulation,\n\tlandmarks = {{}},\n\tsightlines = WorldSpec.sightlines,\n}}\nfor _, region in ipairs(WorldSpec.regions) do\n\ttable.insert(spec.regions, {{\n\t\tid = region.id,\n\t\tkind = region.kind,\n\t\tcentre = Vector3.new(region.centre[1], region.centre[2], region.centre[3]),\n\t\tsize = Vector2.new(region.size[1], region.size[2]),\n\t\tspawn = region.spawn,\n\t\televation = region.elevation,\n\t}})\nend\nfor _, landmark in ipairs(WorldSpec.landmarks) do\n\ttable.insert(spec.landmarks, {{\n\t\tid = landmark.id,\n\t\tat = Vector3.new(landmark.at[1], landmark.at[2], landmark.at[3]),\n\t\theight = landmark.height,\n\t\tvisibleFrom = landmark.visibleFrom,\n\t}})\nend\n\n-- Validated again here. The planner checked this spec, but the spec that\n-- reaches the place is the one that matters, and a mismatch means the emitter\n-- and the planner disagree about what was approved.\nlocal problems = WorldKit.Blockout.validate(spec, tokens)\nif #problems > 0 then\n\terror("[World] the built spec does not validate: " .. table.concat(problems, "; "), 0)\nend\n\nlocal built = WorldKit.Blockout.build(spec, tokens, workspace)\nlocal root = built.root\n\nlocal dressing = Instance.new("Folder")\ndressing.Name = "Dressing"\ndressing.Parent = root\n\n-- How far the world reaches, from the regions themselves rather than a guess.\nlocal far = 0\nfor _, region in ipairs(spec.regions) do\n\tlocal reach = math.max(math.abs(region.centre.X), math.abs(region.centre.Z))\n\t\t+ math.max(region.size.X, region.size.Y) / 2\n\tfar = math.max(far, reach)\nend\nlocal half = far * 1.35\nlocal structures = 0\n\n-- Where a structure already stands.\n--\n-- A landmark region was getting a keep from the landmarks loop and a\n-- building from the region loop, both near its centre, and they grew\n-- through each other -- a tan building body emerging from the side of a\n-- grey tower with its roof wedges cutting the shaft at a diagonal. Every\n-- part of both was exactly where its own spec put it; nothing was asking\n-- whether the ground was already taken.\n--\n-- Circles rather than boxes: structures here are rotated, and a rotated\n-- rectangle overlap test is a lot of code to answer a question a radius\n-- answers well enough. It errs toward refusing, which for a world builder\n-- is the right direction -- a gap reads as planning, an intersection\n-- reads as a bug.\nlocal footprints: {{ {{ at: Vector3, radius: number }} }} = {{}}\n\nlocal function ground_is_free(at: Vector3, radius: number): boolean\n\tfor _, taken in ipairs(footprints) do\n\t\tlocal gap = (Vector3.new(at.X, 0, at.Z)\n\t\t\t- Vector3.new(taken.at.X, 0, taken.at.Z)).Magnitude\n\t\tif gap < (radius + taken.radius) * 0.95 then\n\t\t\treturn false\n\t\tend\n\tend\n\treturn true\nend\n\nlocal function claim(at: Vector3, radius: number): ()\n\ttable.insert(footprints, {{ at = at, radius = radius }})\nend\n-- Half the plaza reach: inside this, the ground is paved.\nlocal extentGuard = far * 0.34\n\n-- `shape` matters more than it looks here. A hill made from a Block has a\n-- flat top and four hard vertical edges, and at ground level that reads as a\n-- green step rather than as ground. A squashed Ball, half sunk, has neither.\nlocal function slab(name: string, size: Vector3, position: Vector3, role: string,\n\tmaterial: Enum.Material, shape: Enum.PartType?): Part\n\tlocal p = Instance.new("Part")\n\tp.Name = name\n\tp.Anchored = true\n\tp.Size = size\n\tp.Position = position\n\tp.Color = tokens:color(role)\n\tp.Material = material\n\tif shape ~= nil then\n\t\tp.Shape = shape\n\tend\n\tp.TopSurface = Enum.SurfaceType.Smooth\n\tp.BottomSurface = Enum.SurfaceType.Smooth\n\tp.Parent = dressing\n\treturn p\nend\n\n-- Ground beyond the blockout, with relief. Grass rather than a flat colour: at\n-- this scale a single tone is most of what makes a plate read as a plate.\nslab("Ground", Vector3.new(half * 4.8, 4, half * 4.8), Vector3.new(0, -3, 0),\n\t"ground", Enum.Material.Grass)\nfor index = 1, 16 do\n\tlocal angle = random:NextNumber(0, math.pi * 2)\n\tlocal distance = random:NextNumber(far * 1.05, half * 1.05)\n\tlocal size = random:NextNumber(60, 150)\n\t-- Sunk past half depth so only the crown shows: a ball resting on the\n\t-- ground is a boulder, a ball buried in it is a rise.\n\tlocal rise = random:NextNumber(12, 34)\n\tlocal mound = slab("Mound",\n\t\tVector3.new(size, rise, size * random:NextNumber(0.6, 1.4)),\n\t\tVector3.new(math.cos(angle) * distance, -rise * 0.58, math.sin(angle) * distance),\n\t\trandom:NextNumber() > 0.5 and "ground" or "groundAlt", Enum.Material.Grass,\n\t\tEnum.PartType.Ball)\n\tmound.Orientation = Vector3.new(0, random:NextNumber(0, 360), 0)\nend\n\n-- Grass in patches, not one colour.\n--\n-- The last plane standing. Panelling the region floors took the frame from\n-- 60% unbroken to 54%, and what was left was the lawn outside them: one\n-- slab the size of the world in a single green. Overlapping patches at two\n-- tones cost a few dozen parts and give the ground a grain the eye can\n-- measure distance against.\nfor index = 1, 34 do\n\tlocal angle = random:NextNumber(0, math.pi * 2)\n\tlocal distance = math.sqrt(random:NextNumber(0.02, 1)) * half\n\tlocal size = random:NextNumber(38, 96)\n\tlocal patch = slab("Patch",\n\t\tVector3.new(size, 1.2, size * random:NextNumber(0.55, 1.5)),\n\t\tVector3.new(math.cos(angle) * distance, -1.6, math.sin(angle) * distance),\n\t\trandom:NextNumber() > 0.45 and \"groundAlt\" or \"vegetationLeafDark\",\n\t\tEnum.Material.Grass)\n\tpatch.Orientation = Vector3.new(0, random:NextNumber(0, 360), 0)\nend\n\n-- Water, which every palette here has declared and nothing has ever built.\n--\n-- `water` has been a role in the token schema since it was written and no\n-- module referenced it, so it was dead data. It earns its place: from any\n-- height it is the one surface that is neither ground nor stone, and an\n-- aerial capture of this map was measuring three distinct hues in the\n-- entire frame.\n--\n-- Placed as pools in the outer band rather than as a moat, because a moat\n-- is a castle idea and this template builds farms and space stations from\n-- the same code. Low, flat and slightly reflective is what reads as water\n-- at distance; a Part cannot be Enum.Material.Water, that is terrain only.\nfor index = 1, 9 do\n\tlocal angle = random:NextNumber(0, math.pi * 2)\n\tlocal distance = random:NextNumber(half * 1.1, half * 1.9)\n\tlocal span = random:NextNumber(70, 165)\n\tlocal pool = slab("Pool",\n\t\tVector3.new(span, 3, span * random:NextNumber(0.5, 1.3)),\n\t\tVector3.new(math.cos(angle) * distance, -1.2, math.sin(angle) * distance),\n\t\t"water", Enum.Material.SmoothPlastic)\n\tpool.Orientation = Vector3.new(0, random:NextNumber(0, 360), 0)\n\tpool.Reflectance = 0.28\n\t-- A rim, so the pool has an edge instead of ending mid-grass.\n\tlocal rim = slab("PoolRim",\n\t\tVector3.new(span * 1.12, 2.2, span * 1.12 * 0.9),\n\t\tVector3.new(math.cos(angle) * distance, -1.8, math.sin(angle) * distance),\n\t\t"stoneSecondary", Enum.Material.Slate)\n\trim.Orientation = pool.Orientation\nend\n\n-- The perimeter. What turns an expanse into a place, and what removes the empty\n-- horizon the measurement was actually reading.\nlocal corners = {{\n\tVector3.new(-half, 0, -half), Vector3.new(half, 0, -half),\n\tVector3.new(half, 0, half), Vector3.new(-half, 0, half),\n}}\nfor index = 1, #corners do\n\tWorldKit.Architecture.wall(dressing, tokens, {{\n\t\tfrom = corners[index],\n\t\tto = corners[(index % #corners) + 1],\n\t\theight = tokens:grammar("buildingMinHeight") * 1.5,\n\t\tstyle = STYLE,\n\t\ttowerSpacing = 150,\n\t}})\nend\n\n-- Outlying towers, at varied heights, beyond the wall.\n--\n-- The skyline was the one axis that would not move: corner towers stand at\n-- the same height on the same square, so from any angle they read as one\n-- line. What breaks a horizon is silhouettes at different distances and\n-- heights, which is why watchtowers sit outside the perimeter.\nfor index = 1, 7 do\n\tlocal angle = (index / 7) * math.pi * 2 + 0.7\n\tlocal distance = half * random:NextNumber(1.06, 1.3)\n\tWorldKit.Architecture.tower(dressing, tokens, {{\n\t\t\tposition = Vector3.new(math.cos(angle) * distance, 0, math.sin(angle) * distance),\n\t\tradius = random:NextNumber(7, 13),\n\t\theight = tokens:grammar(\"buildingMinHeight\") * random:NextNumber(1.2, 2.6),\n\t\tstyle = STYLE,\n\t\tbeacon = index % 3 == 0,\n\t}})\n\tclaim(Vector3.new(math.cos(angle) * distance, 0, math.sin(angle) * distance), 20)\n\tstructures += 1\nend\n\n-- Landmarks the planner declared, as keeps rather than as boxes.\n-- Landmarks claim their ground first. They are the reason their region\n-- exists, so when something has to give way it is not the landmark.\nfor _, landmark in ipairs(spec.landmarks) do\n\tWorldKit.Architecture.tower(dressing, tokens, {{\n\t\tposition = landmark.at,\n\t\tradius = 19,\n\t\t-- Above the wall line, not at the grammar floor.\n\t\t--\n\t\t-- `landmarkMinHeight` is what a landmark needs to read across the\n\t\t-- map from standing height. The keep was built at exactly it, so\n\t\t-- from a rampart looking inward it sat below the horizon and the\n\t\t-- frame had nothing against sky at all.\n\t\theight = math.max(landmark.height,\n\t\t\ttokens:grammar("landmarkMinHeight")) * 2.2,\n\t\tstyle = STYLE,\n\t\tbeacon = true,\n\t}})\n\tclaim(landmark.at, 24)\nend\n\n-- Per region, by kind. Nothing here names a genre: a shop is a shop in every\n-- game that declares one.\nlocal PROPS_BY_KIND = {{\n\tfield = {{ "tree", "tree", "rock" }},\n\tplot = {{ "tree", "rock", "crate" }},\n\tplaza = {{ "crate", "barrel", "banner" }},\n\tstreet = {{ "barrel", "crate" }},\n\tcorridor = {{ "barrel" }},\n\tshop = {{ "crate", "barrel" }},\n\tdecorative = {{ "tree", "rock" }},\n}}\n\nlocal props = 0\nfor _, region in ipairs(spec.regions) do\n\tlocal centre = region.centre\n\tlocal size = region.size\n\tlocal minSide = math.min(size.X, size.Y)\n\tlocal minFootprint = tokens:grammar("buildingMinFootprint")\n\n\tif region.kind == "plaza" or region.spawn == true then\n\t\tWorldKit.Architecture.terrace(dressing, tokens, {{\n\t\t\tcentre = centre, size = Vector2.new(size.X * 0.7, size.Y * 0.7),\n\t\t\tsteps = 3, style = STYLE,\n\t\t}})\n\t\tstructures += 1\n\t\tfor index = 1, 4 do\n\t\t\tlocal angle = (index / 4) * math.pi * 2\n\t\t\tWorldKit.Props.banner(dressing, tokens, {{\n\t\t\t\tposition = centre + Vector3.new(math.cos(angle) * size.X * 0.32, 4,\n\t\t\t\t\tmath.sin(angle) * size.Y * 0.32),\n\t\t\t\tseed = SEED + index,\n\t\t\t}})\n\t\t\tprops += 1\n\t\tend\n\tend\n\n\tif (region.kind == "shop" or region.kind == "interior" or region.kind == "landmark")\n\t\tand minSide >= tokens:grammar("buildingMinFootprint") * 1.6 then\n\t\tlocal count = region.kind == "landmark" and 1 or 2\n\t\tfor index = 1, count do\n\t\t\tlocal angle = random:NextNumber(0, math.pi * 2)\n\t\t\tlocal wide = math.clamp(size.X * 0.4, minFootprint, 52)\n\t\t\tlocal deep = math.clamp(size.Y * 0.4, minFootprint, 44)\n\t\t\tlocal reach = math.max(wide, deep) * 0.5\n\t\t\tlocal at = centre + Vector3.new(math.cos(angle) * size.X * 0.22, 0,\n\t\t\t\tmath.sin(angle) * size.Y * 0.22)\n\t\t\t-- Pushed outward while the ground is taken, then given up on.\n\t\t\t-- A region with no room left for another building is a region\n\t\t\t-- that should not have one, and skipping is what a planner\n\t\t\t-- would do. The alternative is what shipped: a building\n\t\t\t-- growing through the side of the keep it shares a plot with.\n\t\t\tlocal tries = 0\n\t\t\twhile not ground_is_free(at, reach) and tries < 6 do\n\t\t\t\ttries += 1\n\t\t\t\tat = centre + Vector3.new(\n\t\t\t\t\tmath.cos(angle) * size.X * (0.22 + tries * 0.1), 0,\n\t\t\t\t\tmath.sin(angle) * size.Y * (0.22 + tries * 0.1))\n\t\t\tend\n\t\t\tif not ground_is_free(at, reach) then\n\t\t\t\tcontinue\n\t\t\tend\n\t\t\tclaim(at, reach)\n\t\t\tWorldKit.Architecture.building(dressing, tokens, {{\n\t\t\t\tposition = at,\n\t\t\t\tfootprint = Vector2.new(wide, deep),\n\t\t\t\tfloors = random:NextInteger(1, 3),\n\t\t\t\t\trotation = random:NextNumber(0, 360),\n\t\t\t\tstyle = STYLE,\n\t\t\t\tseed = SEED + index,\n\t\t\t}})\n\t\t\tstructures += 1\n\t\tend\n\tend\n\n\tif region.kind == "street" or region.kind == "corridor" then\n\t\tlocal along = math.max(math.floor(math.max(size.X, size.Y) / 40), 1)\n\t\tfor index = -along, along do\n\t\t\tfor _, side in ipairs({{ -1, 1 }}) do\n\t\t\t\tWorldKit.Props.lamp(dressing, tokens, {{\n\t\t\t\t\tposition = centre + Vector3.new(side * size.X * 0.36, 1, index * 40),\n\t\t\t\t\tseed = SEED + index,\n\t\t\t\t}})\n\t\t\t\tprops += 1\n\t\t\tend\n\t\tend\n\tend\n\n\t-- Planting, kept off the centre of every region so nothing lands where the\n\t-- player stands or walks.\n\tlocal kinds = PROPS_BY_KIND[region.kind] or {{ "tree", "rock" }}\n\tlocal density = math.max(math.floor((size.X * size.Y) / 2600), 3)\n\tfor index = 1, density do\n\t\tlocal angle = random:NextNumber(0, math.pi * 2)\n\t\t-- Across the region, not around its rim. Placing at a fixed 0.42-0.5 of\n\t-- the radius ringed every region and left the middle bare -- and the\n\t-- middle is the near field, which is where a player-level frame reads\n\t-- as an empty plane. Square-rooted so the points spread by area rather\n\t-- than bunching toward the centre.\n\tlocal radius = math.sqrt(random:NextNumber(0.04, 0.25))\n\t\tWorldKit.Props.build(kinds[random:NextInteger(1, #kinds)], dressing, tokens, {{\n\t\t\tposition = centre + Vector3.new(\n\t\t\t\tmath.cos(angle) * size.X * radius, 0, math.sin(angle) * size.Y * radius),\n\t\t\trotation = random:NextNumber(0, 360),\n\t\t\tscale = random:NextNumber(0.8, 1.5),\n\t\t\tseed = SEED + index,\n\t\t}})\n\t\tprops += 1\n\tend\nend\n\n-- Ground cover, everywhere. Tufts and pebbles cost nothing at distance and\n-- are most of what stops the near field reading as one flat colour.\nfor index = 1, 260 do\n\tlocal angle = random:NextNumber(0, math.pi * 2)\n\tlocal distance = math.sqrt(random:NextNumber(0.01, 1)) * half * 0.98\n\t-- Ground only. Grass sprouting from a paved plaza reads as a placement\n\t-- bug, and a close capture showed exactly that: green sticks standing\n\t-- on the stone the player walks over.\n\tlocal onPaving = math.abs(math.cos(angle) * distance) < extentGuard\n\t\tand math.abs(math.sin(angle) * distance) < extentGuard\n\tif not onPaving then\n\t\tWorldKit.Props.tuft(dressing, tokens, {{\n\t\tposition = Vector3.new(math.cos(angle) * distance, 0, math.sin(angle) * distance),\n\t\trotation = random:NextNumber(0, 360),\n\t\t\tscale = random:NextNumber(0.7, 1.6),\n\t\t\tseed = SEED + 900 + index,\n\t\t}})\n\t\tprops += 1\n\tend\nend\n\n-- Woodland between the play space and the wall, so the perimeter is arrived at\n-- rather than simply met.\nfor index = 1, 70 do\n\tlocal angle = random:NextNumber(0, math.pi * 2)\n\tlocal distance = random:NextNumber(far * 1.02, half * 0.94)\n\tWorldKit.Props.build(random:NextNumber() > 0.28 and "tree" or "rock", dressing, tokens, {{\n\t\tposition = Vector3.new(math.cos(angle) * distance, 0, math.sin(angle) * distance),\n\t\trotation = random:NextNumber(0, 360),\n\t\tscale = random:NextNumber(0.9, 1.8),\n\t\tseed = SEED + 500 + index,\n\t}})\n\tprops += 1\nend\n\n-- Beyond the wall. The world does not end where the play space does.\n--\n-- Five viewpoints of one build disagreed about whether this scene is\n-- finished: over the shoulder it measured 17% flat, from a rampart 42% and\n-- from 300 studs up 56%. The difference was all outside the perimeter,\n-- where the ground ran to the horizon in one tone because every scatter\n-- loop stopped at `half` -- which is exactly where the wall is. A player\n-- never stands out here. That is not a reason for it to be empty: they look\n-- at it from the rampart, and an aerial capture is mostly this.\nfor index = 1, 120 do\n\tlocal angle = random:NextNumber(0, math.pi * 2)\n\tlocal distance = random:NextNumber(half * 1.06, half * 2.1)\n\tlocal lift = random:NextNumber(8, 40)\n\tlocal patch = slab("Outland",\n\t\tVector3.new(random:NextNumber(70, 190), lift, random:NextNumber(70, 190)),\n\t\tVector3.new(math.cos(angle) * distance, -lift * 0.52,\n\t\t\tmath.sin(angle) * distance),\n\t\trandom:NextNumber() > 0.5 and "groundAlt" or "vegetationLeafDark",\n\t\tEnum.Material.Grass, Enum.PartType.Ball)\n\tpatch.Orientation = Vector3.new(0, random:NextNumber(0, 360), 0)\nend\n\n-- Forest and outcrops to the far edge, thinning with distance so the band\n-- reads as landscape rather than as a second, wider hedge.\nfor index = 1, 150 do\n\tlocal angle = random:NextNumber(0, math.pi * 2)\n\tlocal reach = math.sqrt(random:NextNumber(0.05, 1))\n\tlocal distance = half * (1.08 + reach)\n\tWorldKit.Props.build(random:NextNumber() > 0.24 and "tree" or "rock", dressing, tokens, {{\n\t\tposition = Vector3.new(math.cos(angle) * distance, 0, math.sin(angle) * distance),\n\t\trotation = random:NextNumber(0, 360),\n\t\tscale = random:NextNumber(1.1, 2.4),\n\t\tseed = SEED + 1500 + index,\n\t}})\n\tprops += 1\nend\n\n-- Towers on the far skyline. What a rampart view has to end on: from up\n-- there the perimeter is below the eye, so the horizon behind it was bare.\nfor index = 1, 9 do\n\tlocal angle = (index / 9) * math.pi * 2 + 0.31\n\tlocal distance = half * random:NextNumber(1.7, 2.15)\n\tWorldKit.Architecture.tower(dressing, tokens, {{\n\t\tposition = Vector3.new(math.cos(angle) * distance, 0, math.sin(angle) * distance),\n\t\tradius = random:NextNumber(9, 17),\n\t\theight = tokens:grammar("buildingMinHeight") * random:NextNumber(1.6, 3.4),\n\t\tstyle = STYLE,\n\t\tbeacon = index % 4 == 0,\n\t}})\n\tclaim(Vector3.new(math.cos(angle) * distance, 0, math.sin(angle) * distance), 20)\n\tstructures += 1\nend\n\nPlayers.PlayerAdded:Connect(function(player: Player)\n\tlocal ok, err = pcall(function()\n\t\tWorldKit.Camera.configurePlayer(player, tokens, CAMERA_PROFILE)\n\tend)\n\tif not ok then\n\t\twarn("[{game_id}] camera profile " .. CAMERA_PROFILE .. ": " .. tostring(err))\n\tend\nend)\n\n{asset_pending}\n-- The world declares itself finished.\n--\n-- An attribute rather than a print, so a capture step can wait on the\n-- world instead of sleeping and hoping. Set last, after every loop.\nworkspace:SetAttribute("RQEWorldProps", props)\nworkspace:SetAttribute("RQEWorldStructures", structures)\nworkspace:SetAttribute("RQEWorldReady", true)\n\nprint(string.format(\n\t"[{game_id}] world: mood %s, %d lights, %d regions, %d structures, %d props, %d/%d assets pending",\n\tMOOD, applied.created or 0, #spec.regions, structures, props, pending, #AssetPlan))\n\nreturn built\n'


def _world_source(model: Any, presentation: dict[str, Any], has_assets: bool) -> str:
    """The validated layout, built and then inhabited. See `_SPEC_WORLD_TEMPLATE`."""

    asset_require = (
        "local AssetPlan = require(ReplicatedStorage.Shared.AssetPlan)" + chr(10)
        if has_assets else "local AssetPlan = {}" + chr(10)
    )
    asset_pending = (
        "local pending = 0" + chr(10)
        + "for _, entry in ipairs(AssetPlan) do" + chr(10)
        + chr(9) + "if entry.strategy == " + chr(34) + "CREATE" + chr(34) + " then" + chr(10)
        + chr(9) + chr(9) + "pending += 1" + chr(10)
        + chr(9) + "end" + chr(10) + "end" + chr(10)
        if has_assets
        else "local pending = 0" + chr(10)
    )
    source = _SPEC_WORLD_TEMPLATE.format(
        asset_require=asset_require, asset_pending=asset_pending,
        mood=presentation["mood"], camera=presentation["camera"],
        seed=presentation["seed"], game_id=model.id,
    )
    # Some briefs imply an authored architectural setpiece rather than generic
    # regional dressing.  The decision is still data-driven (presentation), and
    # the implementation remains a reusable WorldKit primitive: the game source
    # only selects and positions it against the validated lane/objective axis.
    # A 180-degree turn puts the sanctuary entrance at +Z (staging) and its bell
    # at -Z (the defended objective) for the tower-defense grammar.
    has_sanctuary = presentation.get("setpiece") == "ruined-sanctuary"
    setpiece_marker = "local structures = 0\n"
    if setpiece_marker not in source:
        raise ImplementError("world structure counter moved before setpiece injection")
    sanctuary_lua = f'''local HAS_SANCTUARY = {str(has_sanctuary).lower()}
if HAS_SANCTUARY then
\tlocal sanctuary = WorldKit.Setpiece.ruinedSanctuary(dressing, tokens, {{
\t\tcframe = CFrame.new(0, 0.6, 0) * CFrame.Angles(0, math.rad(180), 0),
\t\twidth = 126,
\t\tlength = 210,
\t\twallHeight = 34,
\t\tnaveWidth = 38,
\t\tbays = 7,
\t\tseed = SEED,
\t\tfocusKind = "bell",
\t\troles = {{
\t\t\tstone = "stonePrimary",
\t\t\ttrim = "stoneSecondary",
\t\t\tfloor = "pavement",
\t\t\twood = "woodSecondary",
\t\t\tmetal = "metalDark",
\t\t\tfocus = "accentGold",
\t\t}},
\t}})
\tstructures += sanctuary.parts
\tworkspace:SetAttribute("RQEProductSetpiece", "ruined-sanctuary")
\tworkspace:SetAttribute("RQESanctuaryParts", sanctuary.parts)
end
'''
    source = source.replace(
        setpiece_marker, setpiece_marker + sanctuary_lua, 1
    )
    # The authored ruin owns the centre axis.  Keep the generic world as its
    # surrounding landscape, but do not grow a keep, house, plaza or random
    # props through the playable nave.
    landmark_loop = "for _, landmark in ipairs(spec.landmarks) do\n"
    if landmark_loop not in source:
        raise ImplementError("world landmark loop moved before setpiece guard")
    source = source.replace(
        landmark_loop,
        landmark_loop + "\tif HAS_SANCTUARY then\n\t\tcontinue\n\tend\n",
        1,
    )
    source = source.replace(
        'if region.kind == "plaza" or region.spawn == true then',
        'if not HAS_SANCTUARY and (region.kind == "plaza" or region.spawn == true) then',
        1,
    )
    source = source.replace(
        'if (region.kind == "shop" or region.kind == "interior" or region.kind == "landmark")',
        'if not HAS_SANCTUARY and (region.kind == "shop" or region.kind == "interior" or region.kind == "landmark")',
        1,
    )
    density_line = (
        "\tlocal density = math.max(math.floor((size.X * size.Y) / 2600), 3)\n"
    )
    if density_line not in source:
        raise ImplementError("world prop density moved before sanctuary clearing")
    source = source.replace(
        density_line,
        density_line
        + '\tif HAS_SANCTUARY and (region.kind == "plaza" or region.kind == "arena"\n'
        + '\t\tor region.kind == "corridor" or region.kind == "landmark") then\n'
        + "\t\tdensity = 0\n\tend\n",
        1,
    )
    # The palette role owns both colour and surface. The old world template
    # correctly recoloured a horror ground and then forced it back to Grass,
    # leaving an abbey lawn under a moon-cold palette. Preserve explicit water
    # and masonry choices; only the generic terrain calls inherit their role.
    signature = "material: Enum.Material, shape: Enum.PartType?"
    assignment = "p.Material = material"
    if signature not in source or assignment not in source:
        raise ImplementError("world slab helper no longer exposes its material contract")
    source = source.replace(
        signature, "material: Enum.Material?, shape: Enum.PartType?", 1
    ).replace(
        assignment, "p.Material = material or tokens:material(role)", 1
    )
    if source.count("Enum.Material.Grass") < 3:
        raise ImplementError("world terrain no longer has the expected token override sites")
    source = source.replace("Enum.Material.Grass", "nil")
    return source


def _playable_source(model: Any, presentation: dict[str, Any]) -> str:
    """The loop, standing in the world.

    Everything before this emitted systems that existed and a world nobody could
    act on. The catalogue became towers in a Lua table; the economy granted
    currency nothing could spend; the loop was a list of strings. A player
    dropped into it could walk, and that was the whole verb.

    What this adds is the shortest honest path from "systems exist" to "there is
    a game": something in the world to press, a cost to pay, a thing that appears
    when you pay it, and a readout that changes. Four things, and without any one
    of them the other three are invisible.

    Built from the same catalogue the systems were built from, so what a player
    buys is what the content layer generated -- not a placeholder that happens to
    look similar.
    """

    q = chr(34)
    currency = model.currencies[0].id if model.currencies else "cash"

    return f"""--!strict
-- Playable: the loop, standing in the world.
--
-- Systems that exist and a world nobody can act on is not a game. This is the
-- shortest honest path between them: something to press, a cost to pay, a thing
-- that appears, and a number that changes.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

local WorldKit = require(ReplicatedStorage.WorldKit)
local TokenData = require(ReplicatedStorage.Shared.TokenData)
local Catalogue = require(ReplicatedStorage.Shared.Catalogue)
local tokens = WorldKit.Tokens.define(TokenData)

-- The same style the world is built from, so a tower the player raises
-- belongs to the place rather than being dropped onto it.
local STYLE = {{
	wall = "stonePrimary",
	trim = "stoneSecondary",
	roof = "structureSecondary",
	accent = "accentGold",
}}

local Playable = {{}}

--- Build the loop into the world, driven by the systems already constructed.
--- Drivers owns autonomous time. Playable only presents the events it emits;
--- it never starts a second clock that can drift away from session state.
function Playable.build(Gameplay, Drivers)
local systems = Gameplay.systems()

-- Waited for, not assumed. Server Scripts have no guaranteed order, and this
-- one lost the race to the world builder every time -- refusing correctly, for
-- a world that appeared a frame later. Bounded, because waiting forever for
-- something that will never arrive is the same bug with no error message.
local world = nil
local deadline = os.clock() + 10
repeat
	-- By prefix, because the suffix is not ours to predict: a game with no
	-- designed layout gets `Blockout_<id>-synthetic` instead of `-world`,
	-- and the exact-name lookup here matched only the one game that had a
	-- real layout. Nineteen of twenty corpus briefs shipped with no pads,
	-- no objective and no prompts because of this line.
	for _, child in ipairs(workspace:GetChildren()) do
		if string.sub(child.Name, 1, 9) == "Blockout_" then
			world = child
			break
		end
	end
	world = world or workspace:FindFirstChild("World")
	if world == nil then
		task.wait(0.1)
	end
until world ~= nil or os.clock() > deadline

if world == nil then
	-- Refused rather than guessed. Building the loop into a world that is not
	-- there produces prompts floating at the origin, which reads as broken
	-- rather than as absent.
	error("[Playable] no world to build the loop into", 0)
end

local stage = Instance.new("Folder")
stage.Name = "Playable"
stage.Parent = world

--- Where a region actually is, so props stand on the layout rather than beside
--- it. Regions are Models when the blockout built them and Parts otherwise.
local function regionPivot(name: string): CFrame?
	for _, child in ipairs(world:GetChildren()) do
		if child.Name == "Region_" .. name or child.Name == name then
			if child:IsA("Model") then
				return child:GetPivot()
			elseif child:IsA("BasePart") then
				return child.CFrame
			end
		end
	end
	return nil
end

-- The buildable slots, drawn from the layout rather than from coordinates
-- chosen here: a plot the grammar moved takes its slots with it.
local slots: {{ CFrame }} = {{}}
for _, regionName in ipairs({{ "staging", "build_west", "build_east", "arena" }}) do
	local pivot = regionPivot(regionName)
	if pivot ~= nil then
		-- The spawn gets one nearby teaching site, not a barricade of three.
		-- Remaining plots keep their full capacity after the player understands
		-- the verb.  With the old order the highlighted first action was more
		-- than one hundred navigated studs away from the spawn.
		local offsets = if regionName == "staging" then {{ -1 }} else {{ -1, 0, 1 }}
		for _, index in ipairs(offsets) do
			table.insert(slots, pivot * CFrame.new(index * 14, 0, 0))
		end
	end
end
if #slots == 0 then
	table.insert(slots, CFrame.new(0, 0, 0))
end

-- A tower system may consume only a subset of the content catalogue. Building
-- a purchase pad for an enemy id creates a convincing tower in the world that
-- the authoritative store refuses to place. Filter by the system's definitions
-- so every offered purchase can become a real placement.
local buildCatalogue: {{ {{ [string]: any }} }} = {{}}
for _, entry in ipairs(Catalogue) do
	if systems.tower == nil or systems.tower.towers[tostring(entry.id)] ~= nil then
		table.insert(buildCatalogue, entry)
	end
end

local firstBuildSite: Part? = nil
local rewardSource: BasePart? = nil

--- One buildable pad: a plinth, a prompt, and the cost the catalogue set.
local function pad(index: number, at: CFrame, entry: {{ [string]: any }})
	local price = math.max(math.floor((entry.power or 10) * 5), 1)

	-- A prepared foundation, not a marker. A pad that looks like a debug plate
	-- reads as a debug plate however well it works, and "where can I build" is
	-- the first question a tower defense has to answer without words.
	local plinth = Instance.new("Part")
	plinth.Name = "Pad_" .. index
	plinth.Anchored = true
	plinth.Size = Vector3.new(11, 1.4, 11)
	plinth.CFrame = at * CFrame.new(0, 0.7, 0)
	plinth.Color = tokens:color("stoneSecondary")
	plinth.Material = Enum.Material.Cobblestone
	plinth.TopSurface = Enum.SurfaceType.Smooth
	plinth.Parent = stage
	if index == 1 then
		firstBuildSite = plinth
	end

	local deck = Instance.new("Part")
	deck.Name = "Deck"
	deck.Anchored = true
	deck.Size = Vector3.new(8.5, 0.5, 8.5)
	deck.CFrame = plinth.CFrame * CFrame.new(0, 0.95, 0)
	deck.Color = tokens:color("stonePrimary")
	deck.Material = Enum.Material.Slate
	deck.Parent = plinth

	-- Corner posts: the cue that this is a site under construction rather than
	-- a painted square, and the outline that survives at distance.
	for _, corner in ipairs({{
		Vector3.new(1, 0, 1), Vector3.new(-1, 0, 1),
		Vector3.new(1, 0, -1), Vector3.new(-1, 0, -1),
	}}) do
		local post = Instance.new("Part")
		post.Name = "Post"
		post.Anchored = true
		post.Size = Vector3.new(1, 4, 1)
		post.CFrame = plinth.CFrame * CFrame.new(corner.X * 4.6, 2.6, corner.Z * 4.6)
		post.Color = tokens:color("woodSecondary")
		post.Material = Enum.Material.Wood
		post.Parent = plinth
	end

	-- Seated in a socket, not floating over the deck.
	--
	-- The version this replaces hung a 1.4-stud Neon ball 4.6 studs above the
	-- plinth with nothing holding it up, and under bloom it flared into a square
	-- of light -- which is what a debug marker looks like, and "pads e objetivo
	-- parecem debug" was the ninth item on the list of what was wrong with this
	-- scene. A light needs a fitting for the same reason a door needs a frame:
	-- the fitting is what says somebody built it.
	local socket = Instance.new("Part")
	socket.Name = "Socket"
	socket.Anchored = true
	socket.Shape = Enum.PartType.Cylinder
	socket.Size = Vector3.new(1.1, 2.2, 2.2)
	socket.CFrame = deck.CFrame * CFrame.new(0, 0.7, 0) * CFrame.Angles(0, 0, math.rad(90))
	socket.Color = tokens:color("metalDark")
	socket.Material = Enum.Material.Metal
	socket.Parent = plinth

	local marker = Instance.new("Part")
	marker.Name = "Marker"
	marker.Anchored = true
	marker.CanCollide = false
	marker.Shape = Enum.PartType.Ball
	-- Half the diameter it was. Bloom renders an emissive as a disc of its own
	-- size plus the flare, so how big a light source is is a composition
	-- decision before it is a lighting one.
	marker.Size = Vector3.new(0.7, 0.7, 0.7)
	marker.CFrame = deck.CFrame * CFrame.new(0, 1.0, 0)
	marker.Color = tokens:color("accentGold")
	marker.Material = Enum.Material.Neon
	marker.Parent = plinth

	-- A pennant on a mast. Cloth, no emissive: a pad has to read as a claimed
	-- site from across the plaza, and at that distance a silhouette against the
	-- sky carries further than a point of light does.
	local mast = Instance.new("Part")
	mast.Name = "Mast"
	mast.Anchored = true
	mast.Size = Vector3.new(0.35, 7, 0.35)
	mast.CFrame = plinth.CFrame * CFrame.new(-4.6, 8.1, -4.6)
	mast.Color = tokens:color("woodSecondary")
	mast.Material = Enum.Material.Wood
	mast.Parent = plinth

	local pennant = Instance.new("Part")
	pennant.Name = "Pennant"
	pennant.Anchored = true
	pennant.CanCollide = false
	pennant.Size = Vector3.new(2.6, 1.7, 0.12)
	pennant.CFrame = mast.CFrame * CFrame.new(1.4, 2.4, 0)
	pennant.Color = tokens:color("accentGold")
	pennant.Material = Enum.Material.Fabric
	pennant.Parent = plinth

	local prompt = Instance.new("ProximityPrompt")
	prompt.ActionText = "Build " .. tostring(entry.name)
	prompt.ObjectText = tostring(price) .. " {currency}"
	prompt.HoldDuration = 0.4
	prompt.MaxActivationDistance = 14
	prompt.RequiresLineOfSight = false
	prompt.Parent = plinth

	prompt.Triggered:Connect(function(player: Player)
		if systems.economy == nil then
			return
		end
		local position = plinth.Position + Vector3.new(0, 1, 0)
		local placementPosition = {{ position.X, position.Y, position.Z }}

		-- Spatial refusal happens before money moves. There is no yield between
		-- this check, the spend and `place`, so the authoritative transaction
		-- cannot emit a purchase for a placement the Tower store rejected.
		if systems.tower ~= nil then
			local allowed = systems.tower.canPlace(player, tostring(entry.id), placementPosition)
			if not allowed then
				systems.feedback:emit(player, "error", {{
					reasonKey = "invalid", itemName = tostring(entry.name),
					position = plinth.Position,
				}})
				WorldKit.Audio.playAt("denied", plinth)
				return
			end
		end

		-- Spent through the economy, never by editing a number here. Two paths
		-- that move currency is how a ledger stops reconciling.
		local paid = systems.economy:spend(player, {q}{currency}{q}, price, "build:" .. tostring(entry.id))
		if not paid then
			-- Refusal has to be audible. A player who cannot afford a
			-- tower learns it from the sound, not from prompt text that
			-- changed for a second and a half while they looked away.
			WorldKit.Audio.playAt("denied", plinth)
			systems.feedback:emit(player, "error", {{
				reasonKey = "insufficient_funds", itemName = tostring(entry.name),
				position = plinth.Position,
			}})
			prompt.ObjectText = "Need " .. tostring(price) .. " {currency}"
			task.delay(1.5, function()
				prompt.ObjectText = tostring(price) .. " {currency}"
			end)
			return
		end
		player:SetAttribute({q}{currency}{q}, systems.economy:balance(player, {q}{currency}{q}))

		if systems.tower ~= nil then
			local placement = systems.tower.place(
				player, tostring(entry.id), placementPosition)
			if placement == nil then
				-- Defensive rollback for an unexpected refusal. `canPlace` and
				-- `place` are adjacent and should agree; losing currency if they do
				-- not would turn an SDK disagreement into a player-facing theft.
				local balance = systems.economy:grant(
					player, {q}{currency}{q}, price, "rollback:" .. tostring(entry.id))
				player:SetAttribute({q}{currency}{q}, balance)
				systems.feedback:emit(player, "error", {{
					reasonKey = "invalid", itemName = tostring(entry.name),
					position = plinth.Position,
				}})
				return
			end
		end

		-- Built from the same architecture the world is made of, so a tower the
		-- player raises belongs to the place rather than being dropped on it.
		-- A box with a cap on it was the clearest remaining debug object in the
		-- scene, and it was the one the player looks at most.
		WorldKit.Audio.playAt("purchase", plinth)
		local stats = entry.stats or {{}}
		local built = WorldKit.Architecture.tower(stage, tokens, {{
			position = plinth.Position + Vector3.new(0, 1, 0),
			radius = 3.4,
			height = 10 + math.min((stats.attack or 1) * 1.5, 10),
			style = STYLE,
			beacon = false,
		}})
		built.Name = tostring(entry.id)
		local tower = built.PrimaryPart or built:FindFirstChildWhichIsA("BasePart")

		-- A banner in the owner's colour: which towers are mine, readable at a
		-- glance and without a label.
		WorldKit.Props.banner(built, tokens, {{
			position = plinth.Position + Vector3.new(4.2, 1, 0),
			scale = 0.6,
			seed = index,
		}})

		if tower ~= nil then
			WorldKit.Vfx.burst(tokens, tower, {{
				fromRole = "accentGold", toRole = "neutralLight",
				rate = 0, lifetime = NumberRange.new(0.4, 0.9),
				speed = NumberRange.new(6, 10), size = 1.2,
			}}, 18)
		end

		plinth:SetAttribute("built", true)
		marker:Destroy()
		prompt:Destroy()
		systems.feedback:emit(player, "purchase", {{
			itemName = tostring(entry.name), position = plinth.Position,
		}})
		if systems.tower ~= nil then
			systems.feedback:emit(player, "build", {{
				itemName = tostring(entry.name), position = position,
			}})
		end

		-- This effect is recorded only after the spend, authoritative placement
		-- (when present), and world build all succeeded. A prompt trigger is an
		-- attempt; it is never evidence that a purchase happened.
		if systems.onboarding ~= nil then
			local receipt = systems.onboarding.observe(
				player, "purchase_committed",
				"build:" .. tostring(player.UserId) .. ":" .. tostring(index),
				{{ itemId = tostring(entry.id) }})
			if receipt.accepted and index == 1 then
				WorldKit.Guidance.clear(plinth, "first-purchase")
			end
		end
	end)
end

for index, at in ipairs(slots) do
	local entry = buildCatalogue[((index - 1) % math.max(#buildCatalogue, 1)) + 1]
	if entry ~= nil then
		pad(index, at, entry)
	end
end

-- Mark the first site even while inactive, so a black-box probe can distinguish
-- "the cue is off" from "this build exposed no observable target".
local initialSite = firstBuildSite
if initialSite ~= nil then
	WorldKit.Guidance.focus(tokens, initialSite, {{
		id = "first-purchase", action = "Build your first defender",
		role = "accentGold", maxDistance = 70,
	}})
	WorldKit.Guidance.clear(initialSite, "first-purchase")
end

-- Guidance follows the server-published onboarding target. Both authored
-- actions are world targets: the reliquary first, then the nearest foundation.
-- In a shared server a cue remains active while any player still needs it.
local function refreshGuidance()
	local wantsReward = false
	local wantsPurchase = false
	for _, player in ipairs(Players:GetPlayers()) do
		if player:GetAttribute("RQEOnboardingComplete") ~= true then
			local target = player:GetAttribute("RQEOnboardingTarget")
			wantsReward = wantsReward or target == "reward-source"
			wantsPurchase = wantsPurchase or target == "first-purchase"
		end
	end

	local function apply(site: BasePart?, id: string, action: string, wanted: boolean)
		if site == nil then
			return
		end
		local probe = WorldKit.Guidance.probe(stage, id)
		if wanted and not probe.active then
			WorldKit.Guidance.focus(tokens, site, {{
				id = id, action = action, role = "accentGold", maxDistance = 90,
			}})
		elseif not wanted and probe.active then
			WorldKit.Guidance.clear(site, id)
		end
	end

	apply(rewardSource, "reward-source", "Gather embers", wantsReward)
	apply(firstBuildSite, "first-purchase", "Build your first defender", wantsPurchase)
end

local guidanceBound: {{ [Player]: boolean }} = {{}}
local function bindGuidancePlayer(player: Player)
	if guidanceBound[player] then
		return
	end
	guidanceBound[player] = true
	player:GetAttributeChangedSignal("RQEOnboardingTarget"):Connect(refreshGuidance)
	player:GetAttributeChangedSignal("RQEOnboardingComplete"):Connect(refreshGuidance)
	refreshGuidance()
end
Players.PlayerRemoving:Connect(function(player: Player)
	guidanceBound[player] = nil
	task.defer(refreshGuidance)
end)

-- The objective axis. Its focus is defended; the separate spawn-side
-- reliquary below owns the earn verb.
local objective = regionPivot("objective") or CFrame.new(0, 0, -60)

-- Readability, before mechanics. A player looking at one frame has to be able
-- to answer three questions without reading anything: what am I defending,
-- where does the threat come from, and which way does it travel. Text answers
-- none of them, because a player under pressure does not read.
--
-- Built from the same architecture and props as the world, so the answers are
-- part of the place rather than markers laid over it.
local threat = regionPivot("approach") or regionPivot("field")
	or (objective * CFrame.new(0, 0, 220))

-- 1. Where the threat comes from: a breached gate, flanked and lit in the
-- danger colour. A gap in a wall reads as an entrance from any angle.
local gate = Instance.new("Model")
gate.Name = "ThreatGate"
gate.Parent = stage
for _, side in ipairs({{ -1, 1 }}) do
	local pier = Instance.new("Part")
	pier.Name = "Pier"
	pier.Anchored = true
	pier.Size = Vector3.new(7, 26, 7)
	pier.CFrame = threat * CFrame.new(side * 13, 13, 0)
	pier.Color = tokens:color("stoneSecondary")
	pier.Material = Enum.Material.Cobblestone
	pier.Parent = gate

	local brazier = Instance.new("Part")
	brazier.Name = "Brazier"
	brazier.Anchored = true
	brazier.Shape = Enum.PartType.Ball
	brazier.Size = Vector3.new(2.6, 2.6, 2.6)
	brazier.CFrame = pier.CFrame * CFrame.new(0, 14.5, 0)
	brazier.Color = tokens:color("accentDanger")
	brazier.Material = Enum.Material.Neon
	brazier.Parent = gate

	local light = Instance.new("PointLight")
	light.Brightness = 1.2
	light.Range = 22
	light.Color = tokens:color("accentDanger")
	light.Parent = brazier

	WorldKit.Props.banner(gate, tokens, {{
		position = pier.Position + Vector3.new(side * 5, -8, 0),
		accent = "accentDanger", scale = 0.9, seed = side + 40,
	}})
end

local lintel = Instance.new("Part")
lintel.Name = "Lintel"
lintel.Anchored = true
lintel.Size = Vector3.new(33, 5, 8)
lintel.CFrame = threat * CFrame.new(0, 28, 0)
lintel.Color = tokens:color("stonePrimary")
lintel.Material = Enum.Material.Cobblestone
lintel.Parent = gate

-- 2. Which way it travels: a paved lane from the gate to the objective, in the
-- danger colour and edged so it reads as a route rather than as decoration.
local span = (objective.Position - threat.Position)
local distance = span.Magnitude
if distance > 8 then
	local middle = threat.Position:Lerp(objective.Position, 0.5)
	local along = CFrame.lookAt(middle, middle + span.Unit)

	local lane = Instance.new("Part")
	lane.Name = "ThreatLane"
	lane.Anchored = true
	lane.Size = Vector3.new(20, 0.6, distance)
	lane.CFrame = along * CFrame.new(0, 0.4, 0)
	lane.Color = tokens:color("pathAlt")
	lane.Material = Enum.Material.Slate
	lane.Parent = stage

	local edge = Instance.new("Part")
	edge.Name = "LaneEdge"
	edge.Anchored = true
	edge.Size = Vector3.new(24, 0.4, distance)
	edge.CFrame = along * CFrame.new(0, 0.2, 0)
	edge.Color = tokens:color("accentDanger")
	edge.Material = Enum.Material.SmoothPlastic
	edge.Parent = stage

	-- Chevrons pointing at what they threaten. Direction is the one thing a
	-- stripe on the ground cannot say by itself.
	local steps = math.max(math.floor(distance / 26), 1)
	for index = 1, steps do
		local chevron = Instance.new("Part")
		chevron.Name = "Chevron"
		chevron.Anchored = true
		chevron.CanCollide = false
		chevron.Size = Vector3.new(9, 0.3, 3)
		chevron.CFrame = along
			* CFrame.new(0, 0.8, distance / 2 - index * (distance / (steps + 1)))
			* CFrame.Angles(0, math.rad(45), 0)
		chevron.Color = tokens:color("accentDanger")
		chevron.Material = Enum.Material.Neon
		chevron.Transparency = 0.45
		chevron.Parent = stage
	end
end

-- The defended objective is the authored bell when the selected setpiece owns
-- one.  Falling back is explicit and still produces a semantic anchor; a neon
-- debug cube no longer grows through the bell the brief asked for.
local authoredBell = world:FindFirstChild("Bell", true)
local core: BasePart
if authoredBell ~= nil and authoredBell:IsA("BasePart") then
	core = authoredBell
else
	local fallback = Instance.new("Part")
	fallback.Name = "BellObjectiveFallback"
	fallback.Anchored = true
	fallback.Size = Vector3.new(6, 8, 6)
	fallback.CFrame = objective * CFrame.new(0, 5, 0)
	fallback.Color = tokens:color("accentRare")
	fallback.Material = tokens:material("accentRare")
	fallback.Parent = stage
	core = fallback
end
core:SetAttribute("RQEDefendedObjective", "bell")

-- An authored, reachable first verb.  The previous tutorial granted its reward
-- on a timer and advanced itself while the player stood still.  This reliquary
-- is beside the spawn, pays enough for the highlighted foundation, and remains
-- useful afterwards on a bounded cadence.
local reliquaryAt = (regionPivot("staging") or CFrame.new(0, 0, 40))
	* CFrame.new(0, 0, -14)
local reliquary = Instance.new("Model")
reliquary.Name = "EmberReliquary"
reliquary.Parent = stage

local pedestal = Instance.new("Part")
pedestal.Name = "Pedestal"
pedestal.Anchored = true
pedestal.Size = Vector3.new(6, 3, 6)
pedestal.CFrame = reliquaryAt * CFrame.new(0, 1.5, 0)
pedestal.Color = tokens:color("stoneSecondary")
pedestal.Material = tokens:material("stoneSecondary")
pedestal.Parent = reliquary
rewardSource = pedestal

local bowl = Instance.new("Part")
bowl.Name = "Brazier"
bowl.Anchored = true
bowl.Shape = Enum.PartType.Cylinder
bowl.Size = Vector3.new(1.4, 5, 5)
bowl.CFrame = reliquaryAt * CFrame.new(0, 3.7, 0)
	* CFrame.Angles(0, 0, math.rad(90))
bowl.Color = tokens:color("metalDark")
bowl.Material = tokens:material("metalDark")
bowl.Parent = reliquary

local ember = Instance.new("Part")
ember.Name = "Ember"
ember.Anchored = true
ember.CanCollide = false
ember.Shape = Enum.PartType.Ball
ember.Size = Vector3.new(1.7, 1.7, 1.7)
ember.CFrame = reliquaryAt * CFrame.new(0, 5, 0)
ember.Color = tokens:color("accentGold")
ember.Material = Enum.Material.Neon
ember.Parent = reliquary
reliquary.PrimaryPart = pedestal

local emberLight = Instance.new("PointLight")
emberLight.Color = tokens:color("accentGold")
emberLight.Brightness = 1.6
emberLight.Range = 18
emberLight.Parent = ember

local collect = Instance.new("ProximityPrompt")
collect.ActionText = "Gather Embers"
collect.ObjectText = "Reliquary"
collect.HoldDuration = 0.35
collect.MaxActivationDistance = 14
collect.RequiresLineOfSight = false
collect.Parent = pedestal

WorldKit.Guidance.focus(tokens, pedestal, {{
	id = "reward-source", action = "Gather embers",
	role = "accentGold", maxDistance = 90,
}})
WorldKit.Guidance.clear(pedestal, "reward-source")

local lastGather: {{ [number]: number }} = {{}}
collect.Triggered:Connect(function(player: Player)
	local now = os.clock()
	local previous = lastGather[player.UserId] or -math.huge
	if now - previous < 6 then
		systems.feedback:emit(player, "error", {{ reasonKey = "cooldown" }})
		return
	end
	lastGather[player.UserId] = now
	local first = player:GetAttribute("RQEOnboardingTarget") == "reward-source"
	Gameplay.reward(player, if first then 120 else 25, "reliquary")
	WorldKit.Vfx.burst(tokens, ember, {{
		fromRole = "accentGold", toRole = "neutralLight",
		rate = 0, lifetime = NumberRange.new(0.5, 1.0),
		speed = NumberRange.new(8, 14), size = 1.6,
	}}, 24)
	refreshGuidance()
end)

--------------------------------------------------------------- enemies

-- Waves as things that walk, not as arithmetic.
--
-- `Tower.simulate` decided whether a wave is clearable and the drivers applied
-- the damage, and none of it existed in the world: a player watched a counter
-- change. The goal is explicit that the content catalogue has to appear and
-- have a function, and an enemy that is only a row in a table appears nowhere.
--
-- Built from the same catalogue the tower system consumes, so a game with
-- different content gets different enemies without this file knowing anything
-- about the genre.
-- Seeded from the game id, like every other placement: two runs of the same
-- game must put the same enemy in the same lane or a visual comparison between
-- them reports noise instead of change.
local random = Random.new({presentation["seed"]})

local enemyFolder = Instance.new("Folder")
enemyFolder.Name = "Enemies"
enemyFolder.Parent = stage

local function spawnEnemy(entry: {{ [string]: any }}, wave: number)
	local stats = entry.stats or {{}}
	local health = math.max((stats.health or 1) * 20, 20)

	-- A figure, not a marker.
	--
	-- `WorldKit.Threat` builds a faceless hooded humanoid from token colours --
	-- mantle, cowl, no face, its own health bar. It existed, was tested, and had
	-- never reached a game: the enemy here was a red box with a ball on it.
	--
	-- In a horror game the thing coming down the lane *is* the product. A red
	-- marker approaching is a counter going up.
	local model = WorldKit.Threat.build(enemyFolder, tokens, {{
		id = tostring(entry.id),
		cframe = threat * CFrame.new(random:NextNumber(-8, 8), 3.6, 0),
		displayName = tostring(entry.id),
		-- Both, because `maxHealth` defaults to 100 and a tier-3 pilgrim has
		-- more than that; passing only `health` fails its own validator.
		maxHealth = health,
		health = health,
		scale = 1 + math.min((stats.health or 1) * 0.05, 0.45),
		seed = wave * 131 + random:NextInteger(1, 9999),
		bodyRole = "ink",
		mantleRole = "slate",
		faceRole = "neutralLight",
		accentRole = "accentDanger",
		showHealth = true,
	}})
	local body = model.PrimaryPart :: Part

	-- Walks the lane the chevrons point along, so what the readability elements
	-- promise is what actually happens.
	task.spawn(function()
		local travelled = 0
		local remaining = health
		local start = body.Position
		local finish = objective.Position + Vector3.new(0, 3.6, 0)
		local span = (finish - start).Magnitude
		local speed = math.max((stats.speed or 1) * 3, 4)

		while travelled < span and remaining > 0 and body.Parent ~= nil do
			local step = speed * 0.1
			travelled += step
			WorldKit.Threat.pivot(model,
				CFrame.lookAt(start:Lerp(finish, travelled / span), finish))

			-- Damage from whatever is placed, applied here and nowhere else. Two
			-- places subtracting health is how an enemy dies twice and pays out
			-- twice.
			if systems.tower ~= nil then
				local dps = 0
				for _, player in ipairs(Players:GetPlayers()) do
					dps += systems.tower.damage(player)
				end
				remaining -= dps * 0.1
				WorldKit.Threat.setHealth(model, remaining, health)
			end
			task.wait(0.1)
		end

		if remaining <= 0 then
			-- Killed: pay the bounty and say so. A reward with no feedback is a
			-- number that moves while the player is looking somewhere else.
			WorldKit.Vfx.burst(tokens, body, {{
				fromRole = "accentGold", toRole = "neutralLight",
				rate = 0, lifetime = NumberRange.new(0.3, 0.7),
				speed = NumberRange.new(8, 16), size = 1.1,
			}}, 14)
			for _, player in ipairs(Players:GetPlayers()) do
				Gameplay.reward(player, math.max(math.floor(entry.power or 1), 1), "kill")
			end
		else
			WorldKit.Vfx.burst(tokens, core, {{
				fromRole = "accentDanger", toRole = "neutralLight",
				rate = 0, lifetime = NumberRange.new(0.4, 0.8),
				speed = NumberRange.new(6, 12), size = 1.4,
			}}, 18)
		end
		task.wait(0.4)
		model:Destroy()
	end)
end

-- Visual waves are projections of the authoritative Tower wave, not a second
-- simulation. Drivers owns when a wave begins; the same definition used by
-- `Tower.forecast` owns which enemy arrives, how many arrive and their spacing.
-- This is deliberately subscribed before `Drivers.start` in the boot script,
-- so the first event cannot be lost to module startup order.
local catalogueById: {{ [string]: {{ [string]: any }} }} = {{}}
for _, entry in ipairs(Catalogue) do
	catalogueById[tostring(entry.id)] = entry
end

Drivers.on(function(event: string, detail: {{ [string]: any }})
	if event ~= "wave" or systems.tower == nil then
		return
	end

	local round = math.max(math.floor(tonumber(detail.round) or 0), 1)
	local waves = systems.tower.waves
	local definition = waves[math.min(round, #waves)]
	if definition == nil then
		return
	end

	for _, waveEntry in ipairs(definition.entries) do
		local entry = catalogueById[tostring(waveEntry.enemyId)]
		if entry == nil then
			warn(string.format("[Playable] wave %d names missing catalogue entry %s",
				round, tostring(waveEntry.enemyId)))
			continue
		end
		for _ = 1, waveEntry.count do
			spawnEnemy(entry, round)
			task.wait(waveEntry.interval or 0)
		end
	end
end)

-- Bind the two authored cues. Currency is deliberately not granted here: the
-- reliquary is the first playable verb and its committed reward is what moves
-- onboarding to the nearby foundation.
local joined: {{ [number]: boolean }} = {{}}
local function onPlayer(player: Player)
	if joined[player.UserId] then
		return
	end
	joined[player.UserId] = true
	bindGuidancePlayer(player)
end
Players.PlayerAdded:Connect(onPlayer)
for _, player in ipairs(Players:GetPlayers()) do
	onPlayer(player)
end

print(string.format("[{model.id}] playable: %d pads, 1 objective", #slots))
	return stage
end

return Playable
"""


def _telemetry_source(model: Any) -> str:
    return f"""--!strict
-- Telemetry: onboarding and session events.
--
-- Emitted where the event happens rather than where somebody remembered to log
-- it. Without this the first session is unmeasurable, and the first session is
-- the one every other number is judged against.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")

local GameKit = require(ReplicatedStorage.GameKit)

Players.PlayerAdded:Connect(function(player: Player)
\tGameKit.Analytics.onboardingStep(player, 1, "joined")
\tGameKit.Analytics.custom(player, "session_start", 1, {{
\t\tgenre = "{model.genre}",
\t\ttheme = "{model.theme}",
\t}})
end)

return true
"""


_HUD_TEMPLATE = '--!strict\n-- Interface: a HUD bound to the systems, and screens that read them.\n--\n-- The version this replaces built one row with two labels and called it a HUD.\n-- Before that it built nothing at all, because it passed "horizontal" to a\n-- function that takes "row" and took the whole LocalScript down on its first\n-- line -- so the game ran with no interface and the only symptom was an empty\n-- screenshot.\n--\n-- What a HUD has to do, in the order a player needs it:\n--\n-- **Say what changed.** A number that moves when you act is most of what\n-- "the game is responding" feels like. Every readout here is driven by an\n-- attribute the server owns; the client never keeps its own copy, because a\n-- client that does disagrees with the ledger the moment anything is spent, and\n-- it always disagrees in the player\'s favour on screen.\n--\n-- **Say what is happening now, and nothing else.** Wave, integrity and currency\n-- during a round; the result when the round ends. A HUD that shows everything\n-- shows nothing.\n--\n-- **Survive the device it lands on.** Anchored to safe areas rather than to\n-- screen edges, and sized in token steps rather than pixels, so a phone with a\n-- notch and a desktop at 1440p both get a readable layout.\n--\n-- Every colour, size and spacing comes from the token set. A HUD that picks its\n-- own is a second design system that drifts from the world\'s.\n\nlocal Players = game:GetService("Players")\nlocal ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal GuiService = game:GetService("GuiService")\n\nlocal WorldKit = require(ReplicatedStorage.WorldKit)\nlocal TokenData = require(ReplicatedStorage.Shared.TokenData)\nlocal CoreLoop = require(ReplicatedStorage.Shared.CoreLoop)\n\nlocal tokens = WorldKit.Tokens.define(TokenData)\nlocal player = Players.LocalPlayer\nlocal gui = player:WaitForChild("PlayerGui")\n\nlocal Interface = {{}}\n\n-- Safe area, not screen edge. The top inset is where a phone puts its notch and\n-- Roblox puts its own chrome, and a HUD pinned to 0,0 sits under both.\nlocal inset = GuiService:GetGuiInset()\n\nlocal hud = WorldKit.Ui.screen(gui, "HUD", {{ enabled = true }})\n\n--------------------------------------------------------------------- readouts\n\n-- A shelf, not four floating labels.\n--\n-- The readouts used to be drawn straight onto the scene: over a bright\n-- sky the numbers vanished, over a dark wall the glyphs did, and four\n-- separate elements at the same weight gave the eye nothing to land on\n-- first. One contained surface is one thing to glance at.\nlocal top = WorldKit.Ui.shelf(tokens, hud, {{\n\tname = "TopBar",\n\tanchor = Vector2.new(0.5, 0),\n\tposition = UDim2.new(0.5, 0, 0, inset.Y + tokens:space("base")),\n\tsize = UDim2.new(0, 0, 0, 0),\n\tgap = "tight",\n}})\n\n--- One readout, bound to a player attribute the server writes.\n---\n--- Returns the label so a caller can flash it: a number that changes without\n--- announcing itself is a number a player misses while looking elsewhere.\nlocal function readout(caption: string, attribute: string, fallback: string, icon: string?): TextLabel\n\tlocal group = WorldKit.Ui.chip(tokens, top, {{\n\t\tname = caption, icon = icon, value = fallback,\n\t\tstep = "title",\n\t}})\n\tlocal label = group:FindFirstChild("Text", true)\n\tfor _, child in ipairs(group:GetDescendants()) do\n\t\tif child:IsA("TextLabel") and child.Text == fallback then\n\t\t\tlabel = child\n\t\t\tbreak\n\t\tend\n\tend\n\n\tlocal function refresh()\n\t\tlocal value = player:GetAttribute(attribute)\n\t\tif value == nil or label == nil then\n\t\t\treturn\n\t\tend\n\t\tlocal text = if type(value) == "number" then tostring(math.floor(value)) else tostring(value)\n\t\tif (label :: TextLabel).Text ~= text then\n\t\t\t(label :: TextLabel).Text = text\n\t\t\t-- The flash. Feedback for a change the player did not cause is what\n\t\t\t-- makes income legible; without it a rising number is wallpaper.\n\t\t\tWorldKit.Ui.animate(tokens, label, "quick", "standard", {{\n\t\t\t\tTextTransparency = 0,\n\t\t\t}})\n\t\tend\n\tend\n\n\tplayer:GetAttributeChangedSignal(attribute):Connect(refresh)\n\trefresh()\n\treturn label :: TextLabel\nend\n\nreadout("{currency}", "{currency}", "0", "currency")\nreadout("wave", "wave", "-", "wave")\nreadout("integrity", "integrity", "100", "integrity")\nreadout("tier", "nextTier", "-", "tier")\n\n-- Integrity as a proportion as well as a number.\n--\n-- A bare 62 is only meaningful against a maximum the player has to\n-- remember. A bar is the shape of the question they are actually asking,\n-- and its colour carries the urgency faster than the digits do.\nlocal integrityMeter = WorldKit.Ui.meter(tokens, hud, {{\n\tname = "IntegrityMeter",\n\tanchor = Vector2.new(0.5, 0),\n\t-- Centred and wide enough to read as a bar. Left at the default it\n\t-- took its own 168px at a fixed offset and sat under the first chip\n\t-- instead of under the shelf.\n\tposition = UDim2.new(0.5, 0, 0, inset.Y + tokens:space("base") * 4),\n\tsize = UDim2.fromOffset(240, tokens:space("tight")),\n\tfraction = 1,\n}})\nplayer:GetAttributeChangedSignal("integrity"):Connect(function()\n\tlocal value = tonumber(player:GetAttribute("integrity")) or 0\n\tWorldKit.Ui.meterSet(tokens, integrityMeter, value / 100)\nend)\n\n-- Narrow screens get a tighter bar.\n--\n-- Measured on a 760x940 capture, which is the first phone-width evidence\n-- this HUD was ever looked at on: the four readouts reached the toast the\n-- platform draws top-right, and a 375px phone has half again less room.\n-- The gap and the glyphs both come down, so the bar keeps its hierarchy\n-- instead of wrapping into two rows of unrelated numbers.\nlocal layout = top:FindFirstChildOfClass("UIListLayout")\nlocal function fit()\n\tlocal camera = workspace.CurrentCamera\n\tif camera == nil then\n\t\treturn\n\tend\n\tlocal narrow = camera.ViewportSize.X < 820\n\tif layout ~= nil then\n\t\t-- Still a real gap. Tightening this to `tight` was the first\n\t\t-- attempt and it made the bar unreadable: the groups touched and\n\t\t-- the readouts ran together as "4940Tier3". Spacing was never\n\t\t-- what was crowding the bar -- the type size was.\n\t\tlayout.Padding = UDim.new(0, tokens:space(narrow and "base" or "loose"))\n\tend\n\tlocal step = narrow and "body" or "title"\n\tfor _, item in ipairs(top:GetDescendants()) do\n\t\tif item:GetAttribute("RQEIcon") ~= nil then\n\t\t\tlocal side = tokens:text(step)\n\t\t\tlocal frame = item :: Frame\n\t\t\tframe.Size = UDim2.fromOffset(side, side)\n\t\telseif item:IsA("TextLabel") and item.Name == "Amount" then\n\t\t\tlocal label = item :: TextLabel\n\t\t\tlabel.TextSize = tokens:text(step)\n\t\tend\n\tend\nend\n\nif workspace.CurrentCamera ~= nil then\n\tworkspace.CurrentCamera\n\t\t:GetPropertyChangedSignal("ViewportSize"):Connect(fit)\nend\nfit()\n\n-- Audited at the size it ended up, not the size it was designed at. An icon\n-- that passes at 32px and fails at 20 is the failure the goal names, and it\n-- only appears after `fit` has run.\nfor _, problem in ipairs(WorldKit.Ui.audit(gui)) do\n\twarn("[{game_id}] ui narrow: " .. problem)\nend\n\n--------------------------------------------------------- objective and result\n\n-- What to do next, one line, bottom centre. A player who has to open a menu to\n-- find out what the game wants has already stopped playing.\nlocal objective = WorldKit.Ui.panel(tokens, hud, {{\n\tname = "Objective",\n\tanchor = Vector2.new(0.5, 1),\n\tposition = UDim2.new(0.5, 0, 1, -tokens:space("loose")),\n\tsize = UDim2.new(0, 0, 0, 0),\n}})\nobjective.AutomaticSize = Enum.AutomaticSize.XY\nlocal objectiveText = WorldKit.Ui.text(tokens, objective, "body", CoreLoop[1] or "play")\n\n-- Victory and defeat, which every genre has and none of them can leave to text\n-- in the output window.\nlocal banner = WorldKit.Ui.panel(tokens, hud, {{\n\tname = "Result",\n\tanchor = Vector2.new(0.5, 0.5),\n\tposition = UDim2.fromScale(0.5, 0.42),\n\tsize = UDim2.new(0, 0, 0, 0),\n}})\nbanner.AutomaticSize = Enum.AutomaticSize.XY\nbanner.Visible = false\nlocal bannerText = WorldKit.Ui.text(tokens, banner, "display", "")\n\nfunction Interface.announce(kind: string, message: string)\n\tbannerText.Text = message\n\tbannerText.TextColor3 = tokens:color(\n\t\tif kind == "victory" then "accentSuccess"\n\t\telseif kind == "defeat" then "accentDanger"\n\t\telse "neutralLight")\n\tbanner.Visible = true\n\tif kind ~= "victory" and kind ~= "defeat" then\n\t\ttask.delay(2.5, function()\n\t\t\tbanner.Visible = false\n\t\tend)\n\tend\nend\n\n-- The session tells the HUD, rather than the HUD polling it. One announcement\n-- per event means the wave counter and the banner can never disagree about\n-- which wave it is.\nlocal events = ReplicatedStorage:FindFirstChild("RQEClientChannel")\nplayer:GetAttributeChangedSignal("sessionState"):Connect(function()\n\tlocal state = player:GetAttribute("sessionState")\n\tif state == "VICTORY" then\n\t\tWorldKit.Audio.play("victory")\n\t\tInterface.announce("victory", "Held")\n\telseif state == "DEFEAT" then\n\t\tWorldKit.Audio.play("defeat")\n\t\tInterface.announce("defeat", "Fallen")\n\telseif state == "ACTIVE" then\n\t\tobjectiveText.Text = CoreLoop[math.min(2, #CoreLoop)] or "defend"\n\tend\nend)\n\n--------------------------------------------------------------------- screens\n\n--- One screen per template, hidden until asked for, each carrying its empty\n--- state. The first session is the one where every list is empty, and a screen\n--- designed only populated is the one a new player sees broken.\nfunction Interface.build(name: string): ScreenGui\n\tlocal screen = WorldKit.Ui.screen(gui, name, {{ enabled = false, displayOrder = 10 }})\n\tlocal panel = WorldKit.Ui.panel(tokens, screen, {{\n\t\tanchor = Vector2.new(0.5, 0.5),\n\t\tposition = UDim2.fromScale(0.5, 0.5),\n\t}})\n\tWorldKit.Ui.text(tokens, panel, "title", name)\n\n\tif name == "hud" then\n\t\tfor index, step in ipairs(CoreLoop) do\n\t\t\tWorldKit.Ui.text(tokens, panel, "body", index .. ". " .. step)\n\t\tend\n\telseif name == "upgrade_tree" then\n\t\tWorldKit.Ui.text(tokens, panel, "body",\n\t\t\t"Build on a prepared foundation to raise your income.")\n\telse\n\t\tWorldKit.Ui.text(tokens, panel, "body", "Nothing here yet.")\n\tend\n\n\t-- Every screen closes. A screen with no way out is a screen a controller\n\t-- player is trapped in.\n\tlocal close = WorldKit.Ui.button(tokens, panel, "Close")\n\tclose.Activated:Connect(function()\n\t\tscreen.Enabled = false\n\tend)\n\treturn screen\nend\n\nlocal SCREENS = {{ {screens} }}\nlocal screens: {{ [string]: ScreenGui }} = {{}}\nfor _, name in ipairs(SCREENS) do\n\tscreens[name] = Interface.build(name)\nend\n\n-- A way in.\n--\n-- The screens above were built, wired and left unreachable: every one of\n-- them is created with `Enabled = false` and nothing ever set it true. A\n-- menu a player cannot open is the same as a menu nobody wrote, and it is\n-- also why no capture of this game had a screen open in it.\n--\n-- Bottom right, one target, sized from the token scale so it stays within reach of a\n-- thumb on a phone and does not swell on a desktop.\nlocal opener = WorldKit.Ui.stack(tokens, hud, "column", {{\n\tname = "Menu",\n\tanchor = Vector2.new(1, 1),\n\tposition = UDim2.new(1, -tokens:space("base"), 1, -tokens:space("base")),\n\tsize = UDim2.fromOffset(0, 0),\n\tgap = "tight",\n}})\nopener.AutomaticSize = Enum.AutomaticSize.XY\nopener.BackgroundTransparency = 1\n\nfor _, name in ipairs(SCREENS) do\n\tlocal screen = screens[name]\n\tif screen == nil then\n\t\tcontinue\n\tend\n\tlocal label = string.gsub(name, "_", " ")\n\tlocal button = WorldKit.Ui.button(tokens, opener, label)\n\tbutton.Activated:Connect(function()\n\t\t-- One at a time. Two overlapping panels is the state a player\n\t\t-- cannot get out of without knowing which close button is on top.\n\t\tfor other, gui in pairs(screens) do\n\t\t\tgui.Enabled = other == name and not screen.Enabled\n\t\tend\n\tend)\nend\n\n--- Open a screen by name, for anything that is not a finger.\n---\n--- The capture tooling needs it: the goal asks for evidence with the UI\n--- open, and driving a click through VirtualInputManager to get there is a\n--- lot of machinery to prove a panel exists.\nfunction Interface.open(name: string): boolean\n\tlocal screen = screens[name]\n\tif screen == nil then\n\t\treturn false\n\tend\n\tfor other, gui in pairs(screens) do\n\t\tgui.Enabled = other == name\n\tend\n\treturn true\nend\n\n-- Reachable from the client bridge, which cannot require a LocalScript.\n--\n-- One BindableFunction per screen rather than one taking a name: the bridge\n-- command that invokes these accepts a single `argument` and no array, so a\n-- function keyed by name failed schema validation before it reached Studio.\n-- A capture step that has to guess an encoding is one that quietly stops\n-- producing evidence.\nfor _, name in ipairs(SCREENS) do\n\tlocal request = Instance.new("BindableFunction")\n\trequest.Name = "RQEOpen_" .. name\n\trequest.OnInvoke = function()\n\t\treturn Interface.open(name)\n\tend\n\trequest.Parent = gui\n\n\t-- And a way back out, for the same reason: a capture step that opens a\n\t-- screen has to be able to close it, or every later shot is taken\n\t-- through it.\n\tlocal closer = Instance.new("BindableFunction")\n\tcloser.Name = "RQEClose_" .. name\n\tcloser.OnInvoke = function()\n\t\tlocal screen = screens[name]\n\t\tif screen == nil then\n\t\t\treturn false\n\t\tend\n\t\tscreen.Enabled = false\n\t\treturn true\n\tend\n\tcloser.Parent = gui\nend\n\n-- Reachable from the client bridge, which cannot require a LocalScript.\n\n-- Audited rather than assumed. `Ui.audit` reports text below the legibility\n-- distance the token set declares -- the failure nobody sees on a desktop\n-- monitor and every phone player sees immediately.\nfor _, problem in ipairs(WorldKit.Ui.audit(gui)) do\n\twarn("[{game_id}] ui: " .. problem)\nend\n\nprint(string.format("[{game_id}] interface: %d readouts, %d screens",\n\t4, #SCREENS))\n\nreturn Interface\n'


def _interface_source(model: Any, screens: Sequence[str]) -> str:
    """A HUD bound to the systems. See `_HUD_TEMPLATE` for what and why."""

    currency = model.currencies[0].id if model.currencies else "cash"
    listed = ", ".join('"' + name + '"' for name in screens)
    source = _HUD_TEMPLATE.format(
        currency=currency, screens=listed, game_id=model.id,
    )

    def insert_once(needle: str, replacement: str, feature: str) -> None:
        nonlocal source
        if source.count(needle) != 1:
            raise ImplementError(
                f"cannot emit {feature}: expected one interface insertion point, "
                f"found {source.count(needle)}"
            )
        source = source.replace(needle, replacement, 1)

    insert_once(
        """local WorldKit = require(ReplicatedStorage.WorldKit)
local TokenData = require(ReplicatedStorage.Shared.TokenData)
local CoreLoop = require(ReplicatedStorage.Shared.CoreLoop)""",
        """local WorldKit = require(ReplicatedStorage.WorldKit)
local GameKit = require(ReplicatedStorage.GameKit)
local TokenData = require(ReplicatedStorage.Shared.TokenData)
local CoreLoop = require(ReplicatedStorage.Shared.CoreLoop)
local FeedbackConfig = require(ReplicatedStorage.Shared.FeedbackConfig)""",
        "feedback imports",
    )
    insert_once(
        """local Interface = {}

-- Safe area, not screen edge.""",
        """local Interface = {}

-- One semantic packet becomes one toast, one sound and an optional world burst.
-- The bind is client presentation only; GameKit.Feedback exposes no mutation
-- remote, and the presenter never trusts an asset id from the packet.
local feedbackPresenter = WorldKit.Feedback.presenter(tokens, gui, FeedbackConfig)
local feedbackConnection = GameKit.Feedback.bindClient(FeedbackConfig, function(payload)
	feedbackPresenter:present(payload)
end)
Interface.feedbackPresenter = feedbackPresenter
Interface.feedbackConnection = feedbackConnection

-- Safe area, not screen edge.""",
        "feedback presenter",
    )
    insert_once(
        """objective.AutomaticSize = Enum.AutomaticSize.XY
local objectiveText = WorldKit.Ui.text(tokens, objective, "body", CoreLoop[1] or "play")

-- Victory and defeat""",
        """objective.AutomaticSize = Enum.AutomaticSize.XY
local objectiveText = WorldKit.Ui.text(tokens, objective, "body", CoreLoop[1] or "play")
local sessionInstruction = CoreLoop[1] or "play"

-- Onboarding advances only after server-owned effects. Its server presenter
-- publishes this instruction; the client renders it and has no mutation path
-- back into the state machine.
local function refreshObjective()
	local instruction = player:GetAttribute("RQEOnboardingInstruction")
	local complete = player:GetAttribute("RQEOnboardingComplete") == true
	if not complete and type(instruction) == "string" and instruction ~= "" then
		objectiveText.Text = instruction
		objective:SetAttribute("RQEObjectiveSource", "onboarding")
	else
		objectiveText.Text = sessionInstruction
		objective:SetAttribute("RQEObjectiveSource", "session")
	end
end
player:GetAttributeChangedSignal("RQEOnboardingInstruction"):Connect(refreshObjective)
player:GetAttributeChangedSignal("RQEOnboardingComplete"):Connect(refreshObjective)
refreshObjective()

-- Victory and defeat""",
        "onboarding objective",
    )
    insert_once(
        """if state == "VICTORY" then
		WorldKit.Audio.play("victory")
		Interface.announce("victory", "Held")
	elseif state == "DEFEAT" then
		WorldKit.Audio.play("defeat")
		Interface.announce("defeat", "Fallen")
	elseif state == "ACTIVE" then
		objectiveText.Text = CoreLoop[math.min(2, #CoreLoop)] or "defend"
	end""",
        """if state == "VICTORY" then
		Interface.announce("victory", "Held")
	elseif state == "DEFEAT" then
		Interface.announce("defeat", "Fallen")
	elseif state == "ACTIVE" then
		sessionInstruction = CoreLoop[math.min(2, #CoreLoop)] or "defend"
		refreshObjective()
	end""",
        "session objective binding",
    )
    return source


def _project_source(model: Any, has_world: bool) -> str:
    """The Rojo project. The SDK is mapped in beside the game."""

    tree: dict[str, Any] = {
        "$className": "DataModel",
        "ReplicatedStorage": {
            "$className": "ReplicatedStorage",
            # The SDK, mapped from the repository. The game requires it rather
            # than vendoring a copy, so a fix in WorldKit reaches every game.
            "WorldKit": {"$path": "../../roblox/lib/WorldKit"},
            "GameKit": {"$path": "../../roblox/lib/GameKit"},
            "Shared": {"$path": "src/shared"},
        },
        "ServerScriptService": {
            "$className": "ServerScriptService",
            "Gameplay": {"$path": "src/gameplay"},
            "Telemetry": {"$path": "src/telemetry"},
        },
        "StarterPlayer": {
            "$className": "StarterPlayer",
            "StarterPlayerScripts": {
                "$className": "StarterPlayerScripts",
                "Interface": {"$path": "src/interface"},
            },
        },
        "Workspace": {"$className": "Workspace", "$properties": {"Gravity": 196.2}},
        "Lighting": {"$className": "Lighting"},
    }
    tree["ServerScriptService"]["World"] = {"$path": "src/world"}

    return json.dumps({"name": model.id, "tree": tree}, indent=2) + "\n"
